// own setting is kept beside it (see selectTheme()) and comes back first.
if (appearance.theme !== 'studio' && appearance.studioMotion) appearance.motion = appearance.studioMotion;
// Canvas selection can be persisted from an earlier development launch. Keep
// the runtime gate available before normalizing that selection so a real user
// profile cannot abort renderer startup inside the opaque loading cover.
const runtimeInfo = { version: '0.1.0', isDevelopment: false, composableThemeExperiment: false, composableThemeExperimentVersion: 0, composableThemeExperimentProfile: '', composableThemeExperimentLabel: '', composableThemeExperimentTheme: '', composableThemeExperimentStudio: false, composableThemeExperimentCanvasGrid: '', composableThemeExperimentLaunchFlag: false, singularityProbeMode: '', cachePolicy: 'unknown', devCacheToken: '', startedAt: '', platform: 'unknown', versions: {} };
if (appearance.theme === 'foreground' && !canvasStageActive()) {
  appearance.theme = 'studio';
  if (appearance.palette === 'foreground') appearance.palette = appearance.studioPalette || 'gold';
}
// Foundational reset: old built-ins and installed community packages remain
// preserved on disk, but Studio is the sole runtime presentation until its new
// shell is accepted. This also repairs stale durable selections on launch.
const STUDIO_REBUILD_MODE = true;
if (STUDIO_REBUILD_MODE) {
  appearance.theme = 'studio';
  appearance.palette = appearance.studioPalette || 'gold';
}
// Development-only escape hatch for the composable-canvas comparison theme.
// The reset above still fails closed on every launch: the durable selection
// is coerced to Studio before anything paints, and this only takes effect
// after the main process confirms a development runtime that seeded the
// Foreground Stage profile. A packaged build can never satisfy it.
const CANVAS_STAGE_THEME = 'foreground';
const CANVAS_OPT_IN_KEY = 'pixelody.canvasStudioOptIn';
// Readiness and opt-in are separate. The main process seeds the canvas
// runtime on every development launch; this flag is whether the person
// asked for it -- by launch argument, or by the Settings control below,
// which persists so it survives a relaunch.
let canvasOptIn = readPersistedString(CANVAS_OPT_IN_KEY, '') === 'on';
let canvasLaunchDismissed = false;
function canvasRuntimeReady() {
  return runtimeInfo.isDevelopment === true && runtimeInfo.composableThemeExperimentTheme === CANVAS_STAGE_THEME;
}
function canvasStageActive() {
  return canvasRuntimeReady() && !canvasLaunchDismissed && (canvasOptIn || runtimeInfo.composableThemeExperimentLaunchFlag === true);
}

function activeCanvasThemePort() {
  return canvasStageActive() ? canvasThemePortDomain.get(appearance.canvasThemePort) : null;
}

function activePresentationKey() {
  return activeCanvasThemePort()?.key || appearance.theme || 'studio';
}

function cartridgeQuestExperienceActive() {
  return activeCanvasThemePort()?.experience?.key === 'cartridge-quest'
    || activePresentationKey() === 'cartridge-quest';
}

function obsessionExperienceActive() {
  return activeCanvasThemePort()?.experience?.key === 'obsession';
}

// One mark, and it moves. The mark is a single body-owned element in
// canvas-obsession.css; this decides where it sits and what it is pointing at.
// Confirmed playback outranks selection, which outranks keyboard focus, so the
// mark never argues with the thing the listener actually started.
const OBSESSION_MARK_SELECTORS = Object.freeze([
  ['playback', '#trackRows .track-row.playing, .queue-item.playing'],
  ['intent', '#trackRows .track-row.is-selected:not(.playing), .playlist-item.active'],
  ['intent', '#trackRows .track-row:focus-visible, .playlist-item:focus-visible'],
]);
let obsessionMarkFrame = 0;
let obsessionObserver = null;

function obsessionMarkTarget() {
  for (const [state, selector] of OBSESSION_MARK_SELECTORS) {
    const element = document.querySelector(selector);
    if (element) return { state, element };
  }
  return { state: 'rest', element: null };
}

function syncObsessionMark() {
  obsessionMarkFrame = 0;
  if (!obsessionExperienceActive()) {
    delete document.body.dataset.obsessionMark;
    document.body.style.removeProperty('--ob-mark-top');
    document.body.style.removeProperty('--ob-mark-height');
    return;
  }
  const { state, element } = obsessionMarkTarget();
  document.body.dataset.obsessionMark = state;
  if (!element) return;
  const box = element.getBoundingClientRect();
  if (!box.height) return;
  document.body.style.setProperty('--ob-mark-top', `${Math.round(box.top)}px`);
  document.body.style.setProperty('--ob-mark-height', `${Math.round(box.height)}px`);
}

function scheduleObsessionMark() {
  if (obsessionMarkFrame || !obsessionExperienceActive()) return;
  obsessionMarkFrame = requestAnimationFrame(syncObsessionMark);
}

// Typographic pressure. The band is derived from the play count Pixelody
// already keeps in state.playCounts; the count itself is never rendered. Bands
// are coarse on purpose -- a per-play gradient would turn private listening
// into a readable statistic.
function obsessionPressureBand(plays) {
  if (plays >= 24) return '4';
  if (plays >= 10) return '3';
  if (plays >= 4) return '2';
  if (plays >= 2) return '1';
  return '';
}

function syncObsessionPressure() {
  if (!obsessionExperienceActive()) return;
  document.querySelectorAll('#trackRows .track-row[data-id]').forEach((row) => {
    const band = obsessionPressureBand(state.playCounts[decodeURIComponent(row.dataset.id)] || 0);
    if (band) row.dataset.obsessionPressure = band;
    else delete row.dataset.obsessionPressure;
  });
}

// Installed once and left in place: the sweep is mechanic-agnostic, so every
// track navigation mechanic gets both reactions without the mechanics knowing
// this theme exists.
function installObsessionExperience() {
  if (obsessionObserver) return;
  const rows = document.getElementById('trackRows');
  if (!rows) return;
  obsessionObserver = new MutationObserver(() => { syncObsessionPressure(); scheduleObsessionMark(); });
  obsessionObserver.observe(rows, { childList: true, subtree: true, attributeFilter: ['class'] });
  document.addEventListener('focusin', scheduleObsessionMark, true);
  window.addEventListener('resize', scheduleObsessionMark);
  rows.addEventListener('scroll', scheduleObsessionMark, { passive: true });
}

function neonBurstExperienceActive() {
  return activeCanvasThemePort()?.experience?.key === 'neon-burst';
}

let listeningEdition = null;
let listeningEditionKey = '';
function syncListeningEdition() {
  const key = activeCanvasThemePort()?.key || '';
  if (!window.PixelodyListeningEditions?.KEYS.includes(key)) {
    listeningEdition?.destroy(); listeningEdition = null; listeningEditionKey = '';
    return;
  }
  if (key !== listeningEditionKey) {
    listeningEdition?.destroy();
    listeningEdition = window.PixelodyListeningEditions.mount(document.querySelector('.collection-body'), key, (action, opener) => {
      if (action === 'queue.open') { openQueue(opener); return; }
      if (action === 'systems.open') { openSystemsView(opener); return; }
      productionWorkspaceCommand(action);
      const target = action === 'library.open' ? document.querySelector('.library-rail .create-button')
        : action === 'track-information.open' ? document.querySelector('.inspector button')
        : document.querySelector('#trackRows [tabindex="0"], #trackRows button');
      target?.focus();
    });
    listeningEditionKey = listeningEdition ? key : '';
  }
  const published = confirmedPublishedOutputSnapshot();
  const sameSource = published.activeId === currentTrack()?.id;
  listeningEdition?.update({ track: published.track, paused: published.paused, pending: Boolean(published.pending),
    position: sameSource ? audio.currentTime : published.currentTime,
    duration: sameSource && Number.isFinite(audio.duration) ? audio.duration : published.track?.duration,
    bpm: flowTempoValue(published.track), queueLength: activeQueue().length, outputLabel: outputState.activeLabel });
}

// Halftone pitch from the confirmed playing track's real BPM tag. track.bpm is
// read from file metadata at import and is user-editable in the track editor;
// flowTempoValue() is the existing accessor and already returns null for
// anything non-finite or non-positive. The normalisation below is Flow
// Shuffle's own -- (bpm - 55) / 145 clamped to 0.12..1 -- so the screen agrees
// with what the rest of the product already believes about the same track
// instead of offering a second opinion.
//
// Most local libraries are largely untagged, and Pixelody says so out loud
// elsewhere rather than guessing. So an untagged track does NOT get a
// mid-density dot screen, which would read as a measurement that was never
// taken: it gets a line screen at a fixed pitch and an explicit tempo state.
// The untagged pitch deliberately sits outside the 8-15px measured band, so
// pitch alone separates the two even before screen type is read. The pitch is
// recomputed only when the confirmed track changes, so nothing oscillates and
// there is no flash rate to bound.
const NEON_BURST_UNTAGGED_HALFTONE = '19px';

function neonBurstTempo(track) {
  const bpm = flowTempoValue(track);
  if (bpm === null) return { state: 'untagged', halftone: NEON_BURST_UNTAGGED_HALFTONE };
  const energy = Math.max(0.12, Math.min(1, (bpm - 55) / 145));
  return { state: 'tagged', halftone: `${Math.round(16 - (energy * 8))}px` };
}

function syncNeonBurstTempo(track) {
  const tempo = neonBurstTempo(track);
  if (!neonBurstExperienceActive()) {
    delete document.body.dataset.nbTempo;
    document.body.style.removeProperty('--nb-halftone');
    return tempo;
  }
  document.body.dataset.nbTempo = tempo.state;
  document.body.style.setProperty('--nb-halftone', tempo.halftone);
  return tempo;
}

function loFiCafeExperienceActive() {
  return activeCanvasThemePort()?.experience?.key === 'lo-fi-cafe';
}

// The shelf. A collection keeps a stable place because the listener put it
// there, never because the room worked out that it mattered. That distinction
// is the whole of Keepsake: significance the product assigns on your behalf is
// surveillance wearing a friendly face, and the theme would rather show
// nothing than assert something you did not choose.
function cafeAnchored(id) {
  return state.cafeAnchors.includes(String(id || ''));
}

function toggleCafeAnchor(id) {
  const key = String(id || '');
  if (!key) return;
  const index = state.cafeAnchors.indexOf(key);
  if (index >= 0) state.cafeAnchors.splice(index, 1);
  else state.cafeAnchors = [...state.cafeAnchors, key].slice(-12);
  scheduleDurableStatePersist(0, 'settings-change');
  renderPlaylists();
  showToast(index >= 0 ? 'Taken off the shelf.' : 'Kept on the shelf.');
}

function loFiCafeCardAttributes(playlist, save) {
  if (!loFiCafeExperienceActive()) return '';
  const anchored = cafeAnchored(playlist.id);
  const parts = [];
  if (anchored) parts.push(' data-cafe-anchor="true"');
  else if (save.plays > 0) parts.push(' data-cafe-recent="true"');
  parts.push(` data-cafe-wear="${save.plays > 0 ? 'played' : 'none'}"`);
  return parts.join('');
}

// Paper wear. The card already carries real plays and a real last-played time
// for every theme; this only says them in the room's own voice. No superlative,
// no streak, no score -- and where there is no history it says so in words
// instead of falling back to a value that would look measured.
function collectionWearText(playlist, save) {
  const count = save.count;
  if (playlist.dailyMix) return `${count} LOCAL TRACK${count === 1 ? '' : 'S'} &middot; ${escapeHtml(playlist.mix.dateKey)}`;
  if (!loFiCafeExperienceActive()) return `PLAY ${questScoreText(save.plays)} &middot; LAST ${escapeHtml(save.lastPlayed.toUpperCase())}`;
  if (!save.plays) return 'Not played yet';
  const plays = `${save.plays} play${save.plays === 1 ? '' : 's'}`;
  // History is capped at 200 entries, so a collection can genuinely have plays
  // with no surviving record of when. Saying that is more honest than dating it.
  if (/never/i.test(save.lastPlayed)) return `${plays} &middot; last time not recorded`;
  return `${plays} &middot; ${escapeHtml(save.lastPlayed.toLowerCase())}`;
}

// The lamp moves when the music moves. Warmth is taken from the local hour at
// each confirmed track change rather than from a timer, so a room left paused
// is simply a room that has stopped -- which is true, and cheaper than a clock
// nobody is watching. It reaches glow alphas only; it can never move text or
// paper luminance, so the contrast floor holds across the whole range.
function cafeLampWarmth() {
  const spread = Math.abs(new Date().getHours() - 13);
  return Math.max(0, Math.min(1, Math.min(spread, 24 - spread) / 11));
}

function syncLoFiCafeRoom() {
  if (!loFiCafeExperienceActive()) {
    document.body.style.removeProperty('--cafe-lamp');
    return null;
  }
  const lamp = cafeLampWarmth().toFixed(2);
  document.body.style.setProperty('--cafe-lamp', lamp);
  return lamp;
}

function applyCanvasThemePortAttributes(port) {
  document.querySelectorAll('link[href="canvas-listening-editions.css"]').forEach((link) => {
    link.disabled = !window.PixelodyListeningEditions?.KEYS.includes(port?.key);
  });
  const values = {
    canvasThemePort: port?.key || '',
    canvasPortName: port?.name || '',
    canvasPortLayout: port?.hud?.layout || '',
    canvasPortControls: port?.hud?.controls || '',
    canvasPortCorners: port?.hud?.corners || '',
    canvasPortType: port?.typography?.profile || '',
    canvasPortMotion: port?.motion?.profile || '',
    canvasPortIntensity: port?.motion?.intensity || '',
    canvasPortComposition: port?.composition?.layoutKey || '',
  };
  Object.entries(values).forEach(([key, value]) => {
    if (value) document.body.dataset[key] = value;
    else delete document.body.dataset[key];
  });
  document.querySelectorAll('link[rel="stylesheet"][href="canvas-cartridge-quest.css"]').forEach((link) => {
    link.disabled = port?.experience?.stylesheet !== 'canvas-cartridge-quest.css';
  });
  document.querySelectorAll('link[rel="stylesheet"][href="canvas-obsession.css"]').forEach((link) => {
    link.disabled = port?.experience?.stylesheet !== 'canvas-obsession.css';
  });
  document.querySelectorAll('link[rel="stylesheet"][href="canvas-neon-burst.css"]').forEach((link) => {
    link.disabled = port?.experience?.stylesheet !== 'canvas-neon-burst.css';
  });
  document.querySelectorAll('link[rel="stylesheet"][href="canvas-lo-fi-cafe.css"]').forEach((link) => {
    link.disabled = port?.experience?.stylesheet !== 'canvas-lo-fi-cafe.css';
  });
  syncLoFiCafeRoom();
  syncNeonBurstTempo(confirmedPublishedOutputSnapshot().track);
  syncListeningEdition();
  if (port?.experience?.key === 'obsession') {
    installObsessionExperience();
    syncObsessionPressure();
    scheduleObsessionMark();
  } else {
    syncObsessionMark();
  }
  if (port) document.body.dataset.canvasPortTone = isLightColor((paletteDefinitions[port.key] || paletteDefinitions.foreground).bg) ? 'light' : 'dark';
  else delete document.body.dataset.canvasPortTone;
  if (port) {
    document.body.style.setProperty('--canvas-port-gutter', `${port.composition.gap}px`);
    document.body.style.setProperty('--canvas-port-row-base', port.composition.rowBase);
    document.body.style.setProperty('--canvas-port-workspace-padding', port.composition.workspacePadding);
    document.body.style.setProperty('--canvas-port-workspace-height', port.composition.workspaceHeight);
    document.body.style.setProperty('--canvas-port-player-height', `${port.composition.playerHeight}px`);
    document.body.style.setProperty('--canvas-port-player-columns', port.composition.playerColumns);
    document.body.style.setProperty('--canvas-port-player-padding', port.composition.playerPadding);
    document.body.style.setProperty('--canvas-port-player-margin', port.composition.playerMargin);
  } else {
    document.body.style.removeProperty('--canvas-port-gutter');
    document.body.style.removeProperty('--canvas-port-row-base');
    document.body.style.removeProperty('--canvas-port-workspace-padding');
    document.body.style.removeProperty('--canvas-port-workspace-height');
    document.body.style.removeProperty('--canvas-port-player-height');
    document.body.style.removeProperty('--canvas-port-player-columns');
    document.body.style.removeProperty('--canvas-port-player-padding');
    document.body.style.removeProperty('--canvas-port-player-margin');
  }
}
// The theme layer ships linked but disabled so the reset's runtime boundary
// holds exactly: an ordinary launch still loads shared product CSS plus the
// Studio rebuild layer and nothing else.
// Injected rather than declared in index.html so the composable work claims
// no product markup and can be removed without touching the shell.
function installCanvasStudioControl() {
  // Studio is the only selectable theme during the foundation reset, so its
  // development entry must live in the always-visible theme settings group.
  // The former Dev Lab host is correctly hidden outside Dev Lab, which made
  // this control unreachable on every ordinary Studio launch.
  const host = $('.theme-setting');
  if (!host || $('#canvasStudioEntry')) return;
  const group = document.createElement('div');
  group.className = 'cw-studio-entry';
  const button = document.createElement('button');
  button.id = 'canvasStudioEntry';
  button.type = 'button';
  const note = document.createElement('small');
  const portLabel = document.createElement('label');
  portLabel.textContent = 'Canvas theme port';
  const portSelect = document.createElement('select');
  portSelect.id = 'canvasThemePortSelect';
  portSelect.setAttribute('aria-label', 'Canvas theme port');
  const baseOption = document.createElement('option');
  baseOption.value = '';
  baseOption.textContent = 'Canvas Base';
  portSelect.append(baseOption);
  canvasThemePortDomain.PORTS.forEach((port) => {
    const option = document.createElement('option');
    option.value = port.key;
    option.textContent = port.name;
    portSelect.append(option);
  });
  portSelect.value = appearance.canvasThemePort;
  const portNote = document.createElement('small');
  const paintPort = () => {
    const port = canvasThemePortDomain.get(appearance.canvasThemePort);
    const live = canvasStageActive();
    portSelect.value = port?.key || '';
    // A port only paints while Canvas is active. Leaving the select live when
    // it is not means a pick is stored, applyAppearance clears every port
    // attribute because activeCanvasThemePort() is null, and the window
    // repaints identically -- a choice accepted and silently discarded.
    portSelect.disabled = !live;
    portNote.textContent = !live
      ? 'Open Canvas Studio first. Ports only paint while the canvas is active.'
      : port
        ? `${port.summary} Includes its stock module composition; later additions remain separate.`
        : 'Neutral Canvas material. Choose one of the 27 baseline archive ports.';
  };
  const applyPortSelection = async () => {
    const previousKey = appearance.canvasThemePort;
    const nextKey = canvasThemePortDomain.normalizeKey(portSelect.value);
    const nextPort = canvasThemePortDomain.get(nextKey);
    portSelect.disabled = true;
    // The same themed loading screen as any theme change, with the new port's
    // colours and the recoloured logo, before the stock composition swaps in.
    const loadTheme = nextKey || 'foreground';
    const loadVisible = nextKey !== previousKey && canvasStageActive() && showThemeLoadScreen(loadTheme, nextThemeLoadDuration());
    const loadStartedAt = performance.now();
    if (loadVisible) {
      document.body.classList.add('theme-switching');
      await waitForPaint();
      await wait(Math.max(0, (Number($('#themeLoadScreen')?.dataset.enterMs) || 0) - (performance.now() - loadStartedAt)));
    }
    // Whatever happens below, the cover must come down and the picker must come
    // back: an exception between the swap and the reveal used to leave the
    // full-screen loading cover up until the next selection.
    let loadSettled = false;
    try {
      const finishLoad = async () => {
        if (!loadVisible) return;
        await prepareThemeArrival(loadTheme, { visible: true });
        await waitForThemeLoadAnimation();
        loadSettled = true;
        const revealMs = hideThemeLoadScreen();
        startThemeAssetSettle();
        setTimeout(() => document.body.classList.remove('theme-switching'), revealMs);
      };
      if (canvasStageActive() && nextPort) {
        let presetResult;
        try {
          await syncProductionWorkspaceHost();
          presetResult = await productionWorkspaceHost?.applyThemePreset?.({
            key: nextPort.key,
            label: nextPort.name,
            graph: canvasThemePortDomain.graphForPort(nextPort.key),
          });
        } catch (error) {
          presetResult = { ok: false, error: error?.message || 'The stock Canvas composition could not be applied.' };
        }
        if (!presetResult?.ok) {
          appearance.canvasThemePort = previousKey;
          portSelect.value = previousKey;
          portSelect.disabled = false;
          paintPort();
          if (loadVisible) { loadSettled = true; hideThemeLoadScreen(); document.body.classList.remove('theme-switching'); }
          showToast(presetResult?.error || 'Finish or discard the current Canvas draft before switching themes.');
          return;
        }
      }
      appearance.canvasThemePort = nextKey;
      applyAppearance();
      if (navigationDispatcher.setMechanic(activeTrackNavigationMechanic())) {
        syncTrackHeaderVisibility();
        renderTracks({ preserveOrder: true });
      }
      scheduleDurableStatePersist(0, 'settings-change');
      paintPort();
      await finishLoad();
    } finally {
      if (loadVisible && !loadSettled) { hideThemeLoadScreen(); document.body.classList.remove('theme-switching'); }
      portSelect.disabled = !canvasStageActive();
    }
  };
  portSelect.addEventListener('change', applyPortSelection);
  let editionApplying = false;
  window.desktop.onThemeEditionRequest?.(async (key) => {
    if (!['cosmic-cinema', 'neon-burst'].includes(key) || !canvasRuntimeReady()) return;
    if (editionApplying || (canvasStageActive() && portSelect.disabled)) { showToast('A theme change is already in progress. Try Apply again.'); return; }
    editionApplying = true;
    try {
      if (!canvasStageActive()) {
        canvasOptIn = true; canvasLaunchDismissed = false;
        setLocalStorageItem(CANVAS_OPT_IN_KEY, 'on');
        enableCanvasStageStyles();
        await selectTheme(CANVAS_STAGE_THEME);
        await syncProductionWorkspaceHost();
      }
      portSelect.value = key;
      await applyPortSelection();
      paint();
      if (appearance.canvasThemePort === key) showToast(`${canvasThemePortDomain.get(key).name} applied. Return to Studio from Settings > Themes.`);
    } catch (error) { showToast(error?.message || 'The theme edition could not be applied.'); }
    finally { editionApplying = false; }
  });
  portLabel.append(portSelect);
  const paint = () => {
    const on = canvasStageActive();
    button.textContent = on ? 'Leave Canvas Studio' : 'Open Canvas Studio';
    button.setAttribute('aria-pressed', String(on));
    note.textContent = on
      ? 'Composition Mode opens with the canvas. Studio returns on leaving.'
      : 'Opens a near-blank canvas and the rail that builds one. Development only.';
  };
  button.addEventListener('click', async () => {
    const wasActive = canvasStageActive();
    canvasOptIn = !wasActive;
    canvasLaunchDismissed = wasActive;
    setLocalStorageItem(CANVAS_OPT_IN_KEY, canvasOptIn ? 'on' : 'off');
    if (canvasOptIn) enableCanvasStageStyles();
    await selectTheme(canvasOptIn ? CANVAS_STAGE_THEME : 'studio');
    await syncProductionWorkspaceHost();
    // Leaving turns off the sheets only the open canvas uses (a port's
    // experience sheet); the entry's own styling stays.
    if (!canvasOptIn) enableCanvasStageStyles();
    paint();
  });
  paint();
  paintPort();
  group.addEventListener('pixelody-canvas-presentation-change', () => {
    paint();
    paintPort();
  });
  group.append(button, note, portLabel, portNote);
  const notice = host.querySelector('.studio-rebuild-notice');
  if (notice) notice.insertAdjacentElement('afterend', group);
  else host.prepend(group);
}

// Settings > Themes in development builds: what is ready to use and what is
// still being built. The development entries are not registered themes; each
// starts Pixelody the way its Start Pixelody *.cmd launcher does
// (src/development-profiles.js). Canvas opens in place. The
// Singularity routes are chosen when the process starts, so opening or
// leaving one restarts Pixelody, which also means nothing from them can be
// left behind in the Studio window.
const DEVELOPMENT_PRESENTATION_GROUPS = Object.freeze([
  { key: 'active', label: 'Active', note: 'Being built now. Expect changes between launches.' },
  { key: 'paused', label: 'Paused', note: 'Kept exactly as it was left. Open for inspection only.' },
]);

async function restartIntoDevelopmentProfile(profileId) {
  const profiles = Array.isArray(runtimeInfo.developmentProfiles) ? runtimeInfo.developmentProfiles : [];
  const profile = profiles.find((entry) => entry.id === profileId);
  if (!profile || typeof window.desktop?.relaunchDevelopmentProfile !== 'function') return;
  const status = $('#developmentPresentationsStatus');
  const buttons = [...document.querySelectorAll('[data-development-restart]')];
  buttons.forEach((button) => { button.disabled = true; });
  if (status) status.textContent = `Restarting into ${profile.label}...`;
  // Save first. The main process also drains its queue on quit, but a
  // scheduled renderer save only exists in this window.
  if (persistTimer) persist();
  await Promise.resolve(durableStateController.flush('development-restart')).catch(() => null);
  const result = await window.desktop.relaunchDevelopmentProfile(profileId).catch((error) => ({ ok: false, error: error?.message }));
  if (result?.ok) return;
  buttons.forEach((button) => { button.disabled = false; });
  if (status) status.textContent = result?.error || 'Pixelody could not restart.';
}

function developmentRestartButton(profileId, label) {
  const button = document.createElement('button');
  button.type = 'button';
  button.dataset.developmentRestart = profileId;
  button.textContent = label;
  button.addEventListener('click', () => restartIntoDevelopmentProfile(profileId));
  return button;
}

function installDevelopmentExplorer() {
  const profiles = Array.isArray(runtimeInfo.developmentProfiles) ? runtimeInfo.developmentProfiles : [];
  const host = $('.theme-setting');
  const grid = $('#themeSetting');
  if (!profiles.length || !host || !grid || $('#developmentPresentations')) return;
  const current = runtimeInfo.activeDevelopmentProfile || 'studio';
  const currentProfile = profiles.find((profile) => profile.id === current);
  const readyLabel = document.createElement('small');
  readyLabel.className = 'development-presentation-group-label';
  readyLabel.textContent = 'READY TO USE';
  grid.before(readyLabel);
  const section = document.createElement('section');
  section.id = 'developmentPresentations';
  section.className = 'development-presentations';
  section.setAttribute('aria-labelledby', 'developmentPresentationsTitle');
  const head = document.createElement('div');
  head.className = 'development-presentations-head';
  const eyebrow = document.createElement('small');
  eyebrow.textContent = 'DEVELOPMENT BUILD';
  const title = document.createElement('strong');
  title.id = 'developmentPresentationsTitle';
  title.textContent = 'In development';
  const intro = document.createElement('span');
  intro.textContent = 'Work in progress, not registered themes. Each opens on your own library. Singularity routes restart Pixelody, and nothing changed inside them alters how Studio looks.';
  head.append(eyebrow, title, intro);
  section.append(head);
  if (developmentSessionIsolated && currentProfile) {
    const running = document.createElement('div');
    running.className = 'development-presentation-running';
    const note = document.createElement('span');
    note.textContent = `Running ${currentProfile.label}. Appearance and layout changes made here are not saved to Studio.`;
    running.append(note, developmentRestartButton('studio', 'Return to Pixelody Studio'));
    section.append(running);
    // Canvas's in-place toggle would leave this process half in its profile;
    // the restart above is the way back.
    $('.cw-studio-entry')?.remove();
  }
  for (const group of DEVELOPMENT_PRESENTATION_GROUPS) {
    const members = profiles.filter((profile) => profile.group === group.key);
    if (!members.length) continue;
    const wrapper = document.createElement('div');
    wrapper.className = 'development-presentation-group';
    wrapper.dataset.group = group.key;
    const label = document.createElement('small');
    label.className = 'development-presentation-group-label';
    label.textContent = group.label.toUpperCase();
    const note = document.createElement('span');
    note.className = 'development-presentation-group-note';
    note.textContent = group.note;
    const list = document.createElement('ul');
    list.setAttribute('aria-label', `${group.label} development presentations`);
    for (const profile of members) {
      const item = document.createElement('li');
      item.className = 'development-presentation';
      item.dataset.developmentProfile = profile.id;
      item.dataset.current = String(profile.id === current);
      const text = document.createElement('div');
      const name = document.createElement('b');
      name.textContent = profile.label;
      const badge = document.createElement('small');
      badge.textContent = profile.id === current ? 'Running now' : profile.status;
      const summary = document.createElement('span');
      summary.textContent = profile.summary;
      text.append(name, badge, summary);
      item.append(text);
      const canvasEntry = profile.inSession && !developmentSessionIsolated ? $('.cw-studio-entry') : null;
      if (canvasEntry) item.append(canvasEntry);
      else if (profile.id !== current) item.append(developmentRestartButton(profile.id, `Restart into ${profile.label}`));
      list.append(item);
    }
    wrapper.append(label, note, list);
    section.append(wrapper);
  }
  const status = document.createElement('p');
  status.id = 'developmentPresentationsStatus';
  status.className = 'development-presentations-status';
  status.setAttribute('role', 'status');
  status.setAttribute('aria-live', 'polite');
  section.append(status);
  grid.after(section);
}

