function signalImportRecommendedMode(preview) {
  const validation = preview.validation || {};
  const conflicts = preview.conflicts || {};
  const counts = preview.counts || {};
  const currentEvents = Array.isArray(state.signalJournal.events) ? state.signalJournal.events.length : 0;
  const currentTracks = Object.keys(state.signalJournal.trackStats || {}).length;
  const currentSignalItems = currentEvents + currentTracks;
  const skippedItems = Number(conflicts.skipped) || 0;
  const newerCurrentEvents = Number(conflicts.currentNewerEvents) || 0;
  const overlap = Number(conflicts.overlap) || 0;
  const brokenLinks = Number(validation.brokenLinks) || 0;
  const validationIssueCount = Array.isArray(validation.issues) ? validation.issues.length : 0;
  const validationRisk = (Number(validation.errors) || 0) * 4
    + (Number(validation.warnings) || 0)
    + (Number(validation.skippedEvents) || 0) * 2
    + (Number(validation.skippedTrackStats) || 0) * 2
    + (Number(validation.cappedEvents) || 0)
    + brokenLinks * 3;
  const conflictRisk = skippedItems + newerCurrentEvents * 3;
  const incomingSignalItems = (Number(counts.events) || 0) + (Number(counts.trackStats) || 0);
  const undoAvailable = Boolean(signalImportUndoSnapshot);
  const reasons = [];
  let mergeScore = 3;
  let replaceScore = 1;
  if (validationRisk) {
    mergeScore += Math.min(8, validationRisk);
    reasons.push(`${validationIssueCount} validation issue${validationIssueCount === 1 ? '' : 's'} found, so Merge is safer around sanitized data.`);
  } else {
    replaceScore += 2;
    reasons.push('The incoming report validates cleanly.');
  }
  if (brokenLinks) {
    mergeScore += Math.min(6, brokenLinks * 2);
    reasons.push(`${brokenLinks} broken shuffle outcome link${brokenLinks === 1 ? '' : 's'} make Replace riskier.`);
  }
  if (newerCurrentEvents) {
    mergeScore += Math.min(8, newerCurrentEvents * 2);
    reasons.push(`${newerCurrentEvents} newer current event${newerCurrentEvents === 1 ? '' : 's'} would be skipped by Replace.`);
  }
  if (skippedItems) {
    mergeScore += Math.min(6, Math.ceil(skippedItems / 3));
    reasons.push(`${skippedItems} current-only Signal item${skippedItems === 1 ? '' : 's'} are safer to preserve with Merge.`);
  }
  if (!currentSignalItems && incomingSignalItems && !validationRisk) {
    replaceScore += 5;
    reasons.push('There is no current local Signal learning, so Replace is low risk.');
  }
  if (overlap && !newerCurrentEvents && !validationRisk) {
    replaceScore += Math.min(4, Math.ceil(overlap / 4));
    reasons.push(`${overlap} overlapping Signal item${overlap === 1 ? '' : 's'} reduce Replace conflict risk.`);
  }
  if (incomingSignalItems > currentSignalItems * 2 && currentSignalItems < 8 && !validationRisk) {
    replaceScore += 2;
    reasons.push('The incoming report has much more learning data than the current journal.');
  }
  if (!undoAvailable && (conflictRisk || validationRisk)) {
    mergeScore += 1;
    reasons.push('No existing undo snapshot is available, so the preview leans conservative.');
  } else if (undoAvailable) {
    replaceScore += 1;
    reasons.push('An undo snapshot is already available, which slightly lowers restore risk.');
  }
  const mode = replaceScore > mergeScore ? 'replace' : 'merge';
  const confidence = Math.min(96, Math.max(56, 56 + Math.abs(mergeScore - replaceScore) * 6));
  const label = `${mode === 'replace' ? 'Replace' : 'Merge'} recommended`;
  const summary = mode === 'replace'
    ? 'Replace looks reasonable because the import is clean and current local Signal conflict risk is low.'
    : 'Merge is the safer recommendation because it preserves local learning while adding the import where safe.';
  return {
    mode,
    label,
    confidence,
    summary,
    reasons: reasons.slice(0, 5),
    scores: { merge: mergeScore, replace: replaceScore },
    signals: {
      validationRisk,
      conflictRisk,
      currentSignalItems,
      incomingSignalItems,
      overlap,
      newerCurrentEvents,
      brokenLinks,
      undoAvailable,
    },
  };
}
