function signalImportPreviewPayload(payload = {}) {
  const source = signalImportSource(payload);
  if (!source) return null;
  const validation = validateSignalImportPayload(payload, source);
  const journal = validation.journal;
  const settings = source.settings ? normalizeSignalSettings(source.settings) : normalizeSignalSettings(state.signalSettings);
  const flowShuffle = source.flowShuffle ? normalizeFlowShuffle(source.flowShuffle) : normalizeFlowShuffle(state.flowShuffle);
  const events = journal.events || [];
  const shufflePicks = events.filter((event) => event.type === 'shuffle_pick');
  const modeSet = new Set(shufflePicks.map((event) => event.mode).filter(Boolean));
  if (Array.isArray(payload.modeAnalytics)) payload.modeAnalytics.forEach((row) => row?.mode && modeSet.add(row.mode));
  const transitionProfiles = Array.isArray(payload.transitionMemory?.profiles)
    ? payload.transitionMemory.profiles.length
    : transitionMemoryFromEvents(events).rows.length;
  const counts = {
    events: events.length,
    trackStats: Object.keys(journal.trackStats || {}).length,
    shufflePicks: Math.max(shufflePicks.length, Array.isArray(payload.shufflePicks) ? payload.shufflePicks.length : 0),
    linkedOutcomes: countImportedLinkedOutcomes(events, payload),
    modes: modeSet.size,
    trustCalibration: Array.isArray(payload.trustCalibration) ? payload.trustCalibration.length : flowModeAnalytics(events).rows.filter((row) => row.picks).length,
    transitionProfiles,
    trackIntelligence: Math.max(Object.keys(journal.trackStats || {}).length, Array.isArray(payload.trackIntelligence) ? payload.trackIntelligence.length : 0),
  };
  const conflicts = signalImportConflictReview(journal, payload);
  const merge = mergeSignalJournalState(journal, flowShuffle);
  const preview = {
    schema: payload.schema || (payload.signalJournal ? 'pixelody.backup' : 'pixelody.signal-journal'),
    exportedAt: payload.exportedAt || payload.createdAt || '',
    summary: payload.summary || null,
    journal,
    settings,
    flowShuffle,
    counts,
    conflicts,
    merge,
    validation,
  };
  preview.recommendation = signalImportRecommendedMode(preview);
  preview.detailRows = signalImportDetailRows(preview);
  return {
    ...preview,
  };
}
