function textForMemeCue(track) {
  return [track?.title, track?.artist, track?.album, track?.format].filter(Boolean).join(' ');
}
function pickMemeCue(track) {
  if (!track) return null;
  const text = textForMemeCue(track);
  const matched = memeCueRules.find((rule) => rule.test.test(text));
  if (matched) return matched;
  const key = String(track.id || track.title || '');
  const hash = [...key].reduce((total, char) => (total + char.charCodeAt(0)) % 997, 0);
  return defaultMemeCues[hash % defaultMemeCues.length];
}
function updateMemeCue(track = currentTrack()) {
  const overlay = $('#memeNowPlaying');
  if (!overlay) return;
  const trackCue = pickMemeCue(track);
  const cue = trackCue?.dominant && !audio.paused ? trackCue : memeInteractionCue || trackCue;
  const active = Boolean(cue && appearance.theme === 'meme-machine' && (memeInteractionCue || !audio.paused));
  overlay.classList.toggle('active', active);
  document.body.classList.toggle('meme-cue-active', active);
  document.body.dataset.memeCue = active ? cue.id : '';
  if (!cue) {
    document.body.style.removeProperty('--meme-cue-image');
    return;
  }
  const image = $('#memeNowPlayingImage');
  const source = memeAsset(cue.file);
  document.body.style.setProperty('--meme-cue-image', `url("${source}")`);
  if (image && image.getAttribute('src') !== source) image.src = source;
  if (image) image.alt = cue.label;
  $('#memeNowPlayingCode').textContent = cue.code;
  $('#memeNowPlayingLabel').textContent = cue.label;
}
function rotateMemeChaos(reason = 'SCREEN UPDATE', options = {}) {
  if (appearance.theme !== 'meme-machine') return;
  const deckCue = memeChaosDeck[memeChaosIndex % memeChaosDeck.length];
  memeChaosIndex += 1;
  memeInteractionCue = { ...deckCue, code: `MEME / ${reason}` };
  clearTimeout(memeInteractionTimer);
  clearTimeout(memeInvadeTimer);
  document.body.classList.toggle('meme-invading', Boolean(options.invade));
  updateMemeCue(currentTrack());
  memeInteractionTimer = setTimeout(() => {
    memeInteractionCue = null;
    document.body.classList.remove('meme-invading');
    updateMemeCue(currentTrack());
  }, options.duration || 2200);
  if (options.invade) {
    memeInvadeTimer = setTimeout(() => document.body.classList.remove('meme-invading'), 1050);
  }
}
function refreshMemeOnScreenUpdate(reason = 'SCREEN UPDATE') {
  if (appearance.theme !== 'meme-machine') return;
  const now = performance.now();
  if (now - lastMemeScreenUpdate < 420) return;
  lastMemeScreenUpdate = now;
  rotateMemeChaos(reason, { invade: memeChaosIndex % 8 === 0, duration: 1800 });
}
let productionWorkspaceHost = null;
let productionWorkspaceSyncSerial = 0;
let singularityLiveHost = null;

function singularityPlaybackSnapshot() {
  const published = typeof confirmedPublishedOutputSnapshot === 'function' ? confirmedPublishedOutputSnapshot() : { track: null, paused: true };
  return Object.freeze({
    selectedId: selectedTrackActionId || '',
    requestedId: published.pending?.requestedId || '',
    confirmedId: published.track?.id || '',
    paused: Boolean(published.paused),
    failedRequestId: published.failedId || trackBrowserActivationFailedId || '',
  });
}

function syncSingularityLiveHost() {
  const mode = runtimeInfo.isDevelopment === true && ['proxy', 'graph'].includes(runtimeInfo.singularityProbeMode)
    ? runtimeInfo.singularityProbeMode
    : '';
  if (mode && !singularityLiveHost) {
    singularityLiveHost = singularityLiveHostDomain.createHost({ document, readPlayback: singularityPlaybackSnapshot });
  }
  return singularityLiveHost?.setMode(mode) || { ok: true, status: 'inactive' };
}

function productionWorkspaceRead(key) {
  const published = typeof confirmedPublishedOutputSnapshot === 'function' ? confirmedPublishedOutputSnapshot() : { track: null, paused: true };
  const current = published.track;
  if (key === 'library.summary') return { playlistCount: state.playlists.length, trackCount: state.tracks.length, activePlaylistId: state.activePlaylistId || 'all' };
  if (key === 'tracks.summary') return { visibleCount: typeof visibleTracks === 'function' ? visibleTracks().length : state.tracks.length, totalCount: state.tracks.length, activeId: current?.id || null };
  if (key === 'queue.summary') return { count: state.queue.length, currentId: current?.id || null };
  if (key === 'playback.summary') return { id: current?.id || null, title: current?.title || 'Choose a track', artist: current?.artist || '', paused: Boolean(published.paused), position: Number(audio.currentTime) || 0, duration: Number(audio.duration) || Number(current?.duration) || 0 };
  if (key === 'track.information') return { id: current?.id || null, title: current?.title || '', artist: current?.artist || '', album: current?.album || '', format: current?.format || '', codec: current?.codec || '', duration: Number(current?.duration) || 0 };
  if (key === 'signal.frame') return { source: 'c8-deterministic-first-paint', bars: [0.18, 0.42, 0.68, 0.91, 0.74, 0.51, 0.83, 0.62, 0.35, 0.57, 0.77, 0.46] };
  return {};
}

function productionWorkspaceCommand(key) {
  if (key === 'library.open') { layout.libraryCollapsed = false; applyLayout(); return true; }
  if (key === 'tracks.open') { setLibraryVisible(true); return true; }
  if (key === 'queue.open') { $('#queueButton')?.click(); return true; }
  if (key === 'track-information.open') { layout.inspectorCollapsed = false; applyLayout(); return true; }
  if (key === 'settings.open') { $('#settingsButton')?.click(); return true; }
  if (key === 'playback.previous') { $('#prevButton')?.click(); return true; }
  if (key === 'playback.toggle') { $('#playButton')?.click(); return true; }
  if (key === 'playback.next') { $('#nextButton')?.click(); return true; }
  return false;
}

// The composable canvas is owned by whichever profile the main process
// seeded the workspace authority with. 'dev-lab' stays the answer whenever
// no profile is reported, so the original Counterspace Relay path is
// unchanged.
function canvasHostThemeKey() {
  return runtimeInfo.composableThemeExperimentTheme || 'dev-lab';
}

function canvasHostProfileIdentity() {
  if (runtimeInfo.composableThemeExperiment !== true) return false;
  const profileId = runtimeInfo.composableThemeExperimentProfile;
  if (!profileId) return true;
  return { PROFILE_ID: profileId, LABEL: runtimeInfo.composableThemeExperimentLabel || 'Pixelody Canvas', START_IN_USE_MODE: runtimeInfo.composableThemeExperimentStartInUseMode === true };
}

function canvasHostThemePreset() {
  const port = activeCanvasThemePort();
  if (!port) return null;
  return { key: port.key, label: port.name, graph: canvasThemePortDomain.graphForPort(port.key) };
}

async function syncProductionWorkspaceHost() {
  const serial = ++productionWorkspaceSyncSerial;
  const devLabEligible = runtimeInfo.isDevelopment === true && appearance.theme === 'dev-lab';
  const eligible = devLabEligible || (runtimeInfo.isDevelopment === true && appearance.theme === canvasHostThemeKey());
  if (eligible && !productionWorkspaceHost) {
    productionWorkspaceHost = workspaceProductionDomain.createHost({
      document,
      desktop: window.desktop,
      read: productionWorkspaceRead,
      subscribe: () => () => {},
      command: productionWorkspaceCommand,
      announce: (message) => showToast(message),
      experimentProfile: canvasHostProfileIdentity(),
      // Painting is what makes the composition graph the real layout instead
      // of a semantic description of the legacy shell. The player bar is
      // anchored: it moves into its dock whole, so volume, queue, and the
      // mini-player button are not stranded when transport is placed.
      paintCanvas: canvasStageActive(),
      canvasAnchors: [{ nodeId: 'playback-bottom-dock', selector: '.player' }],
      // Canvas Studio is the authoring rail. It only opens for the profile
      // that ships a near-blank canvas; the fixed presets stay read-only.
      canvasStudio: canvasStageActive() && runtimeInfo.composableThemeExperimentStudio === true,
      canvasGridId: runtimeInfo.composableThemeExperimentCanvasGrid || '',
      activeThemeId: canvasHostThemeKey(),
      resolveThemePreset: canvasHostThemePreset,
      returnToLegacy: async () => {
        // An isolated session's process is still in its launch profile;
        // returning in place would leave its layers in Studio.
        if (developmentSessionIsolated) {
          await restartIntoDevelopmentProfile('studio');
          return;
        }
        canvasOptIn = false;
        canvasLaunchDismissed = true;
        setLocalStorageItem(CANVAS_OPT_IN_KEY, 'off');
        disableCanvasStageStyles();
        await selectTheme('studio');
      },
      onFailure: (error) => showToast(`Pixelody Canvas returned to the legacy workspace: ${error.message}`),
    });
  }
  if (!productionWorkspaceHost) return;
  await productionWorkspaceHost.setActive(eligible);
  if (serial !== productionWorkspaceSyncSerial) {
    const currentEligibility = (runtimeInfo.isDevelopment === true && appearance.theme === 'dev-lab') || (runtimeInfo.isDevelopment === true && appearance.theme === canvasHostThemeKey());
    await productionWorkspaceHost.setActive(currentEligibility);
  }
  // The host's controls keep describing Composition Mode on <body> after it
  // deactivates. Every exit (Settings, Return to Studio, a theme change) comes
  // through here, so a Studio window ends up like one that never opened it.
  if (!document.body.classList.contains('cw-production-host-active')) {
    delete document.body.dataset.compositionMode;
    delete document.body.dataset.cwStudioEnabled;
    delete document.body.dataset.cwPointerPhase;
  }
}
