function spawnQuestRewardFloat(label, options = {}) {
  const anchor = $('#questXpCounter') || $('#questXpCell');
  if (!anchor) return;
  const rect = anchor.getBoundingClientRect();
  if (!rect.width && !rect.height) return;
  const milestone = Boolean(options.milestone);
  const level = Boolean(options.level);
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const lifetime = reduced ? 1400 : level ? 4200 : milestone ? 3600 : 3000;
  const floatSeed = (questRewardSerial % 5) - 2;
  const fixedBurst = document.createElement('span');
  fixedBurst.className = `quest-score-floatup${milestone ? ' quest-score-milestone' : ''}${level ? ' quest-score-level' : ''}`;
  fixedBurst.setAttribute('aria-hidden', 'true');
  fixedBurst.textContent = label;
  Object.assign(fixedBurst.style, {
    position: 'fixed',
    zIndex: '2147483647',
    left: `${rect.left + rect.width * 0.5}px`,
    top: `${rect.top - (level ? 26 : milestone ? 16 : 10)}px`,
    opacity: '1',
    pointerEvents: 'none',
    animation: 'none',
    transform: 'translate(-50%, 0) scale(1)',
    filter: 'brightness(1.35)',
    willChange: 'transform, opacity, filter',
  });
  document.body.appendChild(fixedBurst);
  const start = performance.now();
  const frame = (now) => {
    const progress = Math.min(1, (now - start) / lifetime);
    const rise = 1 - Math.pow(1 - progress, 2.15);
    const waft = reduced ? 0 : Math.sin(progress * Math.PI * 2.35 + floatSeed) * (level ? 36 : milestone ? 30 : 22);
    const curl = reduced ? 0 : Math.sin(progress * Math.PI * 6.2 + floatSeed * 0.7) * (level ? 10 : milestone ? 8 : 5);
    const wander = reduced ? 0 : floatSeed * 6 + waft + curl;
    const lift = reduced ? (level ? 118 : milestone ? 96 : 72) * progress : (level ? 330 : milestone ? 280 : 220) * rise;
    let scale = 1;
    if (!reduced) {
      if (progress < 0.1) scale = 0.32 + (progress / 0.1) * (level ? 1.32 : milestone ? 1.18 : 1.05);
      else if (progress < 0.2) scale = (level ? 1.68 : milestone ? 1.5 : 1.37) - ((progress - 0.1) / 0.1) * 0.28;
      else if (progress < 0.34) scale = (level ? 1.34 : milestone ? 1.22 : 1.09) - ((progress - 0.2) / 0.14) * 0.13;
      else scale = (level ? 1.16 : milestone ? 1.09 : 0.96) + Math.sin(progress * Math.PI) * (level ? 0.18 : milestone ? 0.16 : 0.12);
    }
    const opacity = progress < 0.06 ? progress / 0.06 : progress > 0.34 ? Math.max(0, 1 - Math.pow((progress - 0.34) / 0.66, 1.45)) : 1;
    const brightness = 1 + Math.max(0, 1 - progress / 0.22) * (level ? 1.75 : milestone ? 1.35 : 0.78);
    const blur = reduced ? 0 : Math.max(0, (progress - 0.48) / 0.52) * (level ? 1.75 : milestone ? 1.5 : 1.05);
    const transform = `translate(-50%, 0) translate(${wander.toFixed(1)}px, ${(-lift).toFixed(1)}px) scale(${scale.toFixed(3)})`;
    fixedBurst.style.opacity = String(opacity);
    fixedBurst.style.transform = transform;
    fixedBurst.style.filter = `brightness(${brightness.toFixed(2)}) blur(${blur.toFixed(2)}px)`;
    if (progress < 1 && fixedBurst.isConnected) {
      requestAnimationFrame(frame);
    } else {
      fixedBurst.remove();
    }
  };
  requestAnimationFrame(frame);
  setTimeout(() => fixedBurst.remove(), lifetime + 300);
}
