function applyCreatorLayerCosmetics() {
  appearance.creatorLayer = { ...creatorLayerDefaults, ...(appearance.creatorLayer || {}) };
  const settings = appearance.creatorLayer;
  const validOptions = {
    accent: ['blurple', 'emerald', 'rose', 'ember', 'cyan'],
    mood: ['midnight', 'amoled', 'soft'],
    density: ['cozy', 'compact', 'showcase'],
    avatar: ['squircle', 'round', 'tile'],
    rows: ['message', 'compact', 'cards'],
    decor: ['clean', 'status', 'badges'],
  };
  Object.entries(validOptions).forEach(([key, values]) => {
    if (!values.includes(settings[key])) settings[key] = creatorLayerDefaults[key];
  });
  document.body.dataset.creatorAccent = settings.accent;
  document.body.dataset.creatorMood = settings.mood;
  document.body.dataset.creatorDensity = settings.density;
  document.body.dataset.creatorAvatar = settings.avatar;
  document.body.dataset.creatorRows = settings.rows;
  document.body.dataset.creatorDecor = settings.decor;
  document.body.dataset.creatorStudio = settings.studioOpen === false ? 'collapsed' : 'expanded';
  $('#creatorThemeToggle')?.setAttribute('aria-expanded', String(settings.studioOpen !== false));
  if ($('#creatorThemeToggle')) $('#creatorThemeToggle').title = settings.studioOpen === false ? 'Expand Room Style' : 'Collapse Room Style';
  if ($('#creatorThemeToggleState')) $('#creatorThemeToggleState').textContent = settings.studioOpen === false ? 'Show' : 'Hide';
  document.querySelectorAll('[data-creator-option]').forEach((button) => {
    const key = button.dataset.creatorOption;
    button.classList.toggle('active', settings[key] === button.dataset.creatorValue);
  });
}

const questInventorySortLabels = {
  'playlist-order': 'SAVE ORDER',
  'added-desc': 'NEW CARTS',
  'title-asc': 'NAME A-Z',
  'artist-asc': 'HERO A-Z',
  'album-asc': 'SHELF A-Z',
  'quality-desc': 'BEST LOOT',
  'plays-desc': 'HOT SLOTS',
};
const defaultSortLabels = {};
function syncQuestInventoryLabels() {
  const sort = $('#sortSelect');
  if (!sort) return;
  Array.from(sort.options).forEach((option) => {
    if (!defaultSortLabels[option.value]) defaultSortLabels[option.value] = option.textContent;
    option.textContent = cartridgeQuestExperienceActive()
      ? questInventorySortLabels[option.value] || defaultSortLabels[option.value]
      : defaultSortLabels[option.value];
  });
  const orderOption = sort.querySelector('option[value="playlist-order"]');
  if (orderOption && isAlbumCollection()) orderOption.textContent = cartridgeQuestExperienceActive() ? 'TRACK ORDER' : 'Album order';
}

function syncTideplotComposition() {
  const player = document.querySelector('.player');
  const workspace = document.querySelector('.workspace');
  const inspector = $('#inspectorPanel');
  const origin = $('#tideplotPlayerOrigin');
  if (!player || !workspace || !inspector || !origin) return;
  // The Canvas painter owns the complete player as an anchored bottom dock.
  // Re-applying appearance while switching a Canvas port used to run the old
  // Tideplot restoration path and silently pull that anchor back under body,
  // leaving every port at the shared 88px shell height. Canvas teardown will
  // restore the recorded origin itself when the host is actually deactivated.
  if (canvasStageActive() && document.body.classList.contains('cw-production-host-active')) return;
  if (appearance.theme === 'tideplot') {
    if (player.parentElement !== workspace || player.nextElementSibling !== inspector) workspace.insertBefore(player, inspector);
    return;
  }
  if (player.previousElementSibling !== origin || player.parentElement !== origin.parentElement) origin.parentElement.insertBefore(player, origin.nextSibling);
}

function activeCommunityTheme(themeKey = appearance.theme) {
  return communityThemes.get(themeKey || '') || null;
}

function studioRebuildThemeLocked() {
  const integrationThemeException = runtimeInfo.integrationTest?.enabled === true
    && ['workspace-production', 'workspace-theme-experiment', 'theme-package', 'theme-package-write', 'theme-package-read'].includes(runtimeInfo.integrationTest.scenario);
  return STUDIO_REBUILD_MODE && !integrationThemeException;
}

function communityLegacyColors(theme) {
  const tokens = theme?.tokens || {};
  return {
    gold: tokens.accentPrimary,
    gold2: tokens.accentSecondary,
    green: tokens.accentState,
    hero: tokens.heroTone,
    bg: tokens.canvas,
    surface: tokens.elevation1,
    surface2: tokens.elevation2,
    surface3: tokens.elevation3,
    line: tokens.divider,
    edge: tokens.frame,
    text: tokens.foreground,
    muted: tokens.foregroundMuted,
  };
}

function effectiveThemeKey(themeKey = appearance.theme) {
  if (canvasStageActive()) return CANVAS_STAGE_THEME;
  if (studioRebuildThemeLocked()) return 'studio';
  if (activeCommunityTheme(themeKey)) return 'community';
  if (String(themeKey || '').startsWith('community:')) return 'studio';
  if (themeKey === 'foreground' && !canvasStageActive()) return 'studio';
  return themeKey || 'studio';
}

function applyCommunityThemeAttributes(theme) {
  const attributes = {
    communityThemeId: theme?.id || '',
    communityLayout: theme?.hud?.layout || '',
    communityControls: theme?.hud?.controls || '',
    communityCorners: theme?.hud?.corners || '',
    communityType: theme?.typography?.profile || '',
    communityMotion: theme?.motion?.profile || '',
  };
  Object.entries(attributes).forEach(([key, value]) => {
    if (value) document.body.dataset[key] = value;
    else delete document.body.dataset[key];
  });
}

function applyAppearance() {
  const communityTheme = activeCommunityTheme();
  const canvasThemePort = activeCanvasThemePort();
  const paletteKey = canvasThemePort?.key || appearance.palette;
  const custom = !communityTheme && !canvasThemePort && paletteKey === 'custom';
  const customText = isLightColor(appearance.accentBase) ? '#111317' : '#f5f3ef';
  const toneTarget = isLightColor(appearance.accentBase) ? '#000000' : '#ffffff';
  const colors = communityTheme ? communityLegacyColors(communityTheme) : custom ? {
    gold: appearance.accent,
    gold2: mixHex(appearance.accent, customText, .38),
    green: appearance.accentSecondary,
    hero: mixHex(appearance.accentBase, appearance.accent, .28),
    bg: appearance.accentBase,
    surface: mixHex(appearance.accentBase, toneTarget, .045),
    surface2: mixHex(appearance.accentBase, toneTarget, .09),
    surface3: mixHex(appearance.accentBase, toneTarget, .15),
    line: mixHex(appearance.accentBase, toneTarget, .2),
    edge: mixHex(appearance.accentBase, appearance.accent, .42),
    text: customText,
    muted: mixHex(customText, appearance.accentBase, .38),
  } : paletteDefinitions[paletteKey] || paletteDefinitions.gold;
  const root = document.documentElement;
  const variables = { '--gold': colors.gold, '--gold2': colors.gold2, '--green': colors.green, '--hero': colors.hero, '--bg': colors.bg, '--surface': colors.surface, '--surface2': colors.surface2, '--surface3': colors.surface3, '--line': colors.line, '--pixel-edge': colors.edge, '--text': colors.text || '#f5f3ef', '--muted': colors.muted || '#a2a5aa' };
  Object.entries(variables).forEach(([name, value]) => root.style.setProperty(name, value));
  applyBrandMark(communityTheme || canvasThemePort ? colors.gold : '');
  document.body.dataset.detail = appearance.detail;
  document.body.dataset.motion = appearance.motion;
  document.body.dataset.theme = effectiveThemeKey();
  applyCanvasThemePortAttributes(canvasThemePort);
  $('.cw-studio-entry')?.dispatchEvent(new Event('pixelody-canvas-presentation-change'));
  applyCommunityThemeAttributes(communityTheme);
  themeInformationRuntime.setProfile(communityTheme?.information?.profile || themeInformationProfiles[appearance.theme || 'studio'] || null);
  syncThemeInformationUi();
  syncTideplotComposition();
  applyDevLabMechanic();
  queueMicrotask(() => syncProductionWorkspaceHost().catch((error) => console.warn('Pixelody Canvas host sync failed:', error)));
  queueMicrotask(() => {
    const result = syncSingularityLiveHost();
    if (!result.ok) console.warn('Singularity development probe failed:', result.code || result.status);
  });
  applyCreatorLayerCosmetics();
  applyThemeLanguage();
  syncQuestInventoryLabels();
  if (appearance.theme !== 'frosted-void') document.body.classList.remove('bubble-pressed', 'bubble-scrolling');
  document.querySelectorAll('[data-palette]').forEach((button) => button.classList.toggle('active', button.dataset.palette === appearance.palette));
  document.querySelectorAll('[data-theme-option]').forEach((button) => button.classList.toggle('active', button.dataset.themeOption === (appearance.theme || 'studio')));
  $('.custom-palette')?.classList.toggle('active', custom);
  document.querySelectorAll('#detailSetting [data-detail]').forEach((button) => button.classList.toggle('active', button.dataset.detail === appearance.detail));
  document.querySelectorAll('#motionSetting [data-motion]').forEach((button) => button.classList.toggle('active', button.dataset.motion === appearance.motion));
  syncMotionOsOverrideNote();
  document.querySelectorAll('[data-custom-color]').forEach((picker) => { picker.value = appearance[picker.dataset.customColor]; });
  root.style.setProperty('--custom-primary', appearance.accent);
  root.style.setProperty('--custom-secondary', appearance.accentSecondary);
  root.style.setProperty('--custom-base', appearance.accentBase);
  setLocalStorageItem('pixelody.appearance', JSON.stringify(appearance));
  syncInterfaceSoundEngine();
  syncThemePreloader();
  persistStartupLoadColors();
  queueMicrotask(() => {
    if ($('#playlistHero') && $('#playlistCover')) renderHero();
    updateMemeCue();
    broadcastPlayerState();
    if ($('#eqCanvas')?.clientWidth) drawCurve();
  });
}

// Base Pixelody (Studio) shows the user's purple-range logo colour. Any other
// active theme may recolour the in-app mark with its accent, unless the user
// has switched that off. The running window/taskbar icon follows the same resolution.
let appliedBrandIconColor = '';
function applyBrandMark(themeAccent) {
  const mark = brandMarkDomain.resolveMarkColor({ logoColor: appearance.logoColor, logoFollowsTheme: appearance.logoFollowsTheme, themeAccent });
  document.documentElement.style.setProperty('--brand-mark', mark.hex);
  document.body.dataset.brandMarkSource = mark.source;
  document.querySelectorAll('[data-logo-color]').forEach((button) => {
    const active = button.dataset.logoColor === appearance.logoColor;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', String(active));
  });
  const follow = $('#logoFollowsTheme');
  if (follow) follow.checked = appearance.logoFollowsTheme;
  const status = $('#logoColorStatus');
  if (status) {
    const chosen = brandMarkDomain.LOGO_COLORS.find((color) => color.key === appearance.logoColor);
    status.textContent = mark.source === 'theme' ? `Logo and window icon follow the active theme.` : `${chosen.name} logo.`;
  }
  const iconAccent = mark.source === 'theme' ? mark.hex : '';
  const iconIdentity = `${appearance.logoColor}:${iconAccent}`;
  if (appliedBrandIconColor !== iconIdentity && window.desktop?.setBrandIcon) {
    appliedBrandIconColor = iconIdentity;
    window.desktop.setBrandIcon(appearance.logoColor, iconAccent).catch((error) => console.warn('Pixelody window icon update failed:', error));
  }
}

function applyProfileImage() {
  const url = profileImage ? window.desktop.fileUrl(profileImage) : '';
  [$('#profileButton'), $('#profilePreview'), $('#libraryProfile')].forEach((element) => {
    if (!element) return;
    element.style.backgroundImage = url ? `url("${url}")` : '';
    element.classList.toggle('has-image', Boolean(url));
  });
}

const alternateThemes = ['orbital', 'bulkhead', 'graphite-loadout', 'obsession', 'crystal', 'neon-burst', 'monument', 'analog-dossier', 'cosmic-cinema', 'frosted-void', 'obsidian-glass', 'dead-signal', 'meme-machine', 'cartridge-quest', 'sakura-bloom', 'lo-fi-cafe', 'ascii-social', 'poster-pop', 'creator-layer', 'modular-signal', 'cut-sheet', 'acid-transit', 'ghost-index', 'violet-violent', 'abyssal-press', 'harmonic-registry', 'axis-break', 'tideplot', 'counterform-choir', 'aftergarden', 'vesperfold', 'dev-lab', 'foreground'];
// Runtime theme key -> track-browsing navigation mechanic key
// (theme-runtime/navigation/). This is the Phase 2 stand-in for reading
// `navigation.trackBrowser` out of each theme's *.theme.json manifest: the
// running app has no runtime path to those files yet (see
// docs/themes/THEME_RUNTIME_ARCHITECTURE.md), so this small hardcoded map is
// the source of truth today, the same way paletteDefinitions/alternateThemes
// above already are for palette data. Only trackBrowser exists here --
// there is no playlist-browsing mechanic dispatcher (manifest.navigation
// also allows playlistBrowser, but nothing in renderer.js consumes it yet).
