function normalizedLoadColors(colors = {}) {
  const bg = colors.bg || '#050607';
  const surface = colors.surface || bg;
  const accent = colors.gold || '#d8b66a';
  const accent2 = colors.gold2 || colors.green || accent;
  const text = colors.text || (isLightColor(bg) ? '#111317' : '#f5f3ef');
  const muted = colors.muted || mixHex(text, bg, .38);
  return { bg, surface, accent, accent2, text, muted };
}

function activeThemeLoadColors() {
  const styles = getComputedStyle(document.documentElement);
  const read = (name, fallback) => styles.getPropertyValue(name).trim() || fallback;
  return {
    bg: read('--bg', '#050607'),
    surface: read('--surface', '#101112'),
    accent: read('--gold', '#d8b66a'),
    accent2: read('--gold2', '#f1d497'),
    text: read('--text', '#f5f3ef'),
    muted: read('--muted', '#a2a5aa'),
  };
}

function paletteLoadColors(palette) {
  if (palette === 'custom') {
    const text = isLightColor(appearance.accentBase) ? '#111317' : '#f5f3ef';
    const toneTarget = isLightColor(appearance.accentBase) ? '#000000' : '#ffffff';
    return normalizedLoadColors({
      gold: appearance.accent,
      gold2: mixHex(appearance.accent, text, .38),
      green: appearance.accentSecondary,
      bg: appearance.accentBase,
      surface: mixHex(appearance.accentBase, toneTarget, .045),
      text,
      muted: mixHex(text, appearance.accentBase, .38),
    });
  }
  return normalizedLoadColors(paletteDefinitions[palette] || paletteDefinitions.gold);
}

function targetThemeLoadColors(theme) {
  const requested = theme || 'studio';
  const communityTheme = activeCommunityTheme(requested);
  const port = canvasThemePortDomain.get(requested);
  if (port) return paletteLoadColors(port.key);
  if (requested === CANVAS_STAGE_THEME) {
    const activePort = activeCanvasThemePort();
    if (activePort) return paletteLoadColors(activePort.key);
  }
  if (communityTheme) return normalizedLoadColors(communityLegacyColors(communityTheme));
  const palette = requested === 'studio'
    ? (alternateThemes.includes(appearance.palette) ? appearance.studioPalette || 'gold' : appearance.palette || appearance.studioPalette || 'gold')
    : requested;
  return paletteLoadColors(palette);
}

// The loading screen is static markup that paints before any script runs, so
// the next launch's colours are stored for startup-load-colors.js (a head
// script) to apply to the very first frame. Otherwise every launch showed the
// default gold screen first and then dissolved into the saved theme's colours.
function persistStartupLoadColors() {
  try {
    const theme = canvasStageActive() ? (appearance.canvasThemePort || CANVAS_STAGE_THEME) : appearance.theme || 'studio';
    const to = targetThemeLoadColors(theme);
    const from = startupThemeLoadColors(to);
    const mark = brandMarkDomain.resolveMarkColor({ logoColor: appearance.logoColor, logoFollowsTheme: appearance.logoFollowsTheme, themeAccent: theme === 'studio' ? '' : to.accent }).hex;
    const stored = {
      fromBg: from.bg, fromSurface: from.surface, fromAccent: from.accent, fromAccent2: from.accent2,
      toBg: to.bg, toSurface: to.surface, toAccent: to.accent, toAccent2: to.accent2,
      text: to.text, muted: to.muted, mark,
    };
    if (Object.values(stored).every((value) => /^#[0-9a-f]{6}$/i.test(String(value)))) setLocalStorageItem('pixelody.startupLoadColors', JSON.stringify(stored));
    else localStorage.removeItem('pixelody.startupLoadColors');
  } catch {
    // Startup colours are a nicety; never let them break a theme change.
  }
}

function startupThemeLoadColors(colors) {
  const shadow = isLightColor(colors.bg) ? '#f7f1e6' : '#020304';
  return {
    bg: mixHex(colors.bg, shadow, .46),
    surface: mixHex(colors.surface, shadow, .38),
    accent: mixHex(colors.accent, colors.bg, .2),
    accent2: mixHex(colors.accent2, colors.surface, .18),
    text: colors.text,
    muted: colors.muted,
  };
}

function themeLoadDisplayName(theme) {
  const option = document.querySelector(`[data-theme-option="${CSS.escape(theme || 'studio')}"] b`);
  if (option?.textContent) return option.textContent.trim();
  if ((theme || 'studio') === 'studio') return 'Pixelody Studio';
  return String(theme || 'studio').split('-').map((word) => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
}

function shouldShowThemeLoad(theme) {
  const requested = theme || 'studio';
  const current = appearance.theme || 'studio';
  return requested !== current || (requested === 'studio' && alternateThemes.includes(appearance.palette));
}

// Choosing a theme is a small ceremony: the themed loading screen plays in full
// for the first few selections. Only someone flipping through several themes in
