  const to = targetThemeLoadColors(theme);
  const mark = brandMarkDomain.resolveMarkColor({ logoColor: appearance.logoColor, logoFollowsTheme: appearance.logoFollowsTheme, themeAccent: theme === 'studio' ? '' : to.accent });
  screen.style.setProperty('--brand-mark', mark.hex);
  const from = options.fromColors || (options.mode === 'startup' ? startupThemeLoadColors(to) : activeThemeLoadColors());
