    '--theme-load-from-bg': from.bg,
    '--theme-load-from-surface': from.surface,
    '--theme-load-from-accent': from.accent,
    '--theme-load-from-accent-2': from.accent2,
    '--theme-load-to-bg': to.bg,
    '--theme-load-to-surface': to.surface,
