function buildEqControls(container, type) {
  container.innerHTML = bands.map((band) => `<div class="eq-control" data-eq-band="${band.id}"><label>${band.label}<small class="eq-frequency">${band.frequency >= 1000 ? `${(band.frequency / 1000).toFixed(1)} kHz` : `${band.frequency} Hz`}</small></label><div class="eq-slider-shell"><input type="range" min="${-EQ_GAIN_LIMIT_DB}" max="${EQ_GAIN_LIMIT_DB}" step="0.5" value="0" data-band="${band.id}" aria-label="${band.label} equalizer gain"></div><strong>0.0 dB</strong></div>`).join('');
  container.addEventListener('input', (event) => {
    const input = event.target.closest('input'); if (!input) return;
    const value = clampNumber(input.value, -EQ_GAIN_LIMIT_DB, EQ_GAIN_LIMIT_DB, 0);
    input.value = value;
    let values;
    if (type === 'track') {
      if (!currentTrack()) { syncEqControls(); showToast('Select a track to tune it.'); return; }
      values = normalizeTuning(state.tunings[currentTrack().id] || tuningDefault()); state.tunings[currentTrack().id] = values;
    } else {
      stopCalibrationPreview();
      values = normalizeTuning(state.systems[currentSystemId()] || tuningDefault()); state.systems[currentSystemId()] = values;
    }
    values[input.dataset.band] = value;
  input.closest('.eq-control').querySelector('strong').textContent = `${value.toFixed(1)} dB`;
  syncQuestPowerMeter(input.closest('.eq-control'), value);
  questTuningEncounterToast(type);
  schedulePersist(); applyEq(); scheduleTrackRender({ preserveOrder: true });
  });
}
