function renderDiagnosticsSnapshot(snapshot) {
  const setText = (selector, value) => { const element = $(selector); if (element) element.textContent = value; };
  setText('#diagApp', `${snapshot.app.mode} v${snapshot.app.version} / Electron ${snapshot.app.electron}`);
  setText('#diagCache', snapshot.cache.devCacheToken ? `${snapshot.cache.policy} / ${snapshot.cache.devCacheToken}` : snapshot.cache.policy);
  setText('#diagOutput', `${snapshot.output.activeLabel} / ${snapshot.output.status}`);
  setText('#diagEngine', snapshot.audio.engine);
  setText('#diagSource', `${snapshot.audio.source} / headroom ${snapshot.audio.safety.headroomDb} dB`);
  setText('#diagRenderer', `${snapshot.renderer.performanceMode} / ${snapshot.renderer.theme} / ${snapshot.renderer.motion} / ${snapshot.renderer.firstInteractiveMs || 0} ms interactive / input ${snapshot.renderer.lastInteractionDelayMs || 0} ms / ${snapshot.renderer.trackRender.rows || 0}/${snapshot.renderer.trackRender.total || 0} rows`);
  setText('#diagStorage', `${formatBytes(snapshot.storage.localStorageBytes)} / persist ${snapshot.storage.lastPersistMs} ms`);
  setText('#diagLibrary', `${snapshot.storage.tracks} tracks / ${snapshot.storage.queue} queued`);
  const durable = snapshot.storage.durable;
  const durableSummary = durable.lastWriteAt
    ? `${durable.lastWriteMs} ms, ${formatBytes(durable.lastWriteBytes)} via "${durable.lastWriteReason || 'unknown'}"${durable.lastWriteLargestKey ? ` (largest: ${durable.lastWriteLargestKey} / ${formatBytes(durable.lastWriteLargestKeyBytes)})` : ''}`
    : 'No durable write yet';
  setText('#diagPersist', durableSummary);
  updateOutputModeReadout();
  updateDeviceDiagnostics();
}

const diagnosticsController = diagnosticsDomain.createDiagnosticsController({
  buildSnapshot: buildDiagnosticsSnapshot,
  renderSnapshot: renderDiagnosticsSnapshot,
});
function diagnosticsSnapshot() { return diagnosticsController.snapshot(); }
// About a hundred state changes request a diagnostics refresh, often several
// in one interaction, and each render builds a full snapshot; one render per
// frame shows the same final state.
let diagnosticsRenderFrame = 0;
function updateDiagnostics() {
  if (diagnosticsRenderFrame) return;
  diagnosticsRenderFrame = requestAnimationFrame(() => {
    diagnosticsRenderFrame = 0;
    diagnosticsController.render();
  });
}

function clearRendererRuntimeState() {
  RUNTIME_CLEAN_STORAGE_KEYS.forEach((key) => localStorage.removeItem(key));
  clearTimeout(themeLoadTimer);
  clearTimeout(themeLoadResetTimer);
  lastThemeLoadStartedAt = 0;
  themeLoadRapidCount = 0;
  hideThemeLoadScreen();
  resetThemeContinuationState();
  diagnosticsState.lastConserveReason = '';
  diagnosticsState.lastLongTask = 0;
  diagnosticsState.lastSlowFrame = 0;
  diagnosticsState.eqPeakDb = 0;
  diagnosticsState.headroomDb = 0;
  diagnosticsState.masterGain = 1;
  diagnosticsState.spatialBalance = 0;
  diagnosticsState.spatialMono = false;
  diagnosticsState.calibrationStatus = 'Idle';
  diagnosticsState.toneStatus = 'Idle';
  diagnosticsState.toneError = '';
  diagnosticsState.toneRoute = outputState.activeLabel;
  state.systemPreview = null;
  stopSpeakerTestTone('Idle.', { resumeMusic: false });
  playbackSlowScore = 0;
  playbackStableFrames = 0;
  playbackConserveUntil = 0;
  clearTimeout(playbackPerformanceRecoveryTimer);
  playbackPerformanceRecoveryTimer = 0;
  Object.assign(layout, layoutDefaults);
  setPlaybackPerformance('full');
}

async function cleanRuntimeState() {
  if (!confirm('Clean transient runtime caches and reload Pixelody? Your music, playlists, artwork, theme, and audio tuning stay saved.')) return;
  playInterfaceSound('press', { key: 'clean-runtime', force: true });
  clearRendererRuntimeState();
  let report = null;
  try {
    report = await window.desktop.clearRuntimeCache?.();
  } catch (error) {
    report = { error: error.message || String(error) };
  }
  diagnosticsState.lastRuntimeClear = { at: new Date().toISOString(), report };
  updateDiagnostics();
  showToast('Runtime cleaned. Reloading...');
  setTimeout(() => location.reload(), 450);
}

async function initializeRuntimeInfo() {
  try {
    Object.assign(runtimeInfo, await window.desktop.getRuntimeInfo());
    document.body.dataset.runtimeMode = runtimeInfo.isDevelopment ? 'development' : 'packaged';
    document.body.dataset.platform = runtimeInfo.platform || 'unknown';
    document.body.classList.add(`platform-${runtimeInfo.platform || 'unknown'}`);
    updatePlatformShortcutsUi();
    if (runtimeInfo.devCacheToken) document.body.dataset.devCacheToken = runtimeInfo.devCacheToken;
    // The canvas gate has three independent ways to be false and no visible
    // failure of its own: without this line a missing launch flag looks
    // exactly like a broken host. Lands in Pixelody-console-log.txt.
    console.info(`Pixelody Canvas gate: development=${runtimeInfo.isDevelopment} profile=${runtimeInfo.composableThemeExperimentProfile || 'none'} theme=${runtimeInfo.composableThemeExperimentTheme || 'none'} studio=${runtimeInfo.composableThemeExperimentStudio === true} active=${canvasStageActive()} singularity=${runtimeInfo.singularityProbeMode || 'none'}`);
    developmentSessionIsolated = runtimeInfo.activeDevelopmentProfileIsolated === true;
    if (canvasRuntimeReady()) {
      // The entry control's own styling lives in the theme layer, so the
      // sheet has to be enabled before the button exists rather than only
      // once the canvas is opened.
      enableCanvasStageStyles();
      installCanvasStudioControl();
    }
    installDevelopmentExplorer();
    if (canvasStageActive()) {
      enableCanvasStageStyles();
      // This development-only handoff happens during the existing startup
      // reveal. Starting a second full-screen theme load here can race the
      // startup cover and extend the blocked launch well past its bound.
      if (appearance.theme !== CANVAS_STAGE_THEME) await selectTheme(CANVAS_STAGE_THEME, { skipLoad: true });
    }
    await syncProductionWorkspaceHost();
    const singularityResult = syncSingularityLiveHost();
    if (!singularityResult.ok) throw new Error(`Singularity development probe failed: ${singularityResult.code || singularityResult.status}`);
    if (runtimeInfo.singularityProbeMode) {
      console.info(`Singularity probe gate: mode=${runtimeInfo.singularityProbeMode} status=${singularityResult.status} ready=${document.body.dataset.singularityProbeReady === 'true'}`);
    }
    console.info('Pixelody runtime', diagnosticsSnapshot());
  } catch (error) {
    runtimeInfo.cachePolicy = 'unavailable';
    console.warn('Pixelody runtime diagnostics unavailable:', error);
  } finally {
    // Painted readiness can precede this deferred Canvas/runtime reconcile.
    // Publish an explicit boundary so diagnostics and integration work never
    // begin authoring against a host that can still be replaced underneath it.
    document.body.dataset.runtimeInfoReady = 'true';
  }
  updateDiagnostics();
}

const DAILY_CURATED_RECIPE = dailyCurated.REDISCOVERY_RECIPE;
const DAILY_CURATED_COLLECTION_ID = dailyCurated.collectionId(DAILY_CURATED_RECIPE);
let dailyMixNeedsPersist = false;

function dailyMixDurationText(seconds = 0) {
  const totalSeconds = Math.max(0, Number(seconds) || 0);
  if (!totalSeconds) return 'Unknown';
  if (totalSeconds < 60) return '< 1 min';
  const totalMinutes = Math.max(1, Math.round(totalSeconds / 60));
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  return hours ? `${hours} hr ${String(minutes).padStart(2, '0')} min` : `${minutes} min`;
}

function dailyMixLocalDate(dateKey = dailyCurated.dayKey()) {
  const [year, month, day] = String(dateKey).split('-').map(Number);
  const date = new Date(year, Math.max(0, (month || 1) - 1), day || 1);
  return Number.isFinite(date.getTime()) ? date : new Date();
}

function dailyMixDateLabel(dateKey) {
  return new Intl.DateTimeFormat(undefined, { weekday: 'long', month: 'long', day: 'numeric' }).format(dailyMixLocalDate(dateKey));
}

// Scoring a 10,000-track library is long, synchronous work. The planner is a
// generator that yields between slices so the app can run it a slice per idle
// moment; the synchronous adapter below simply runs it to the end.
const DAILY_CURATED_SCORE_SLICE = 400;
function* dailyCuratedPlanSteps({ candidates = [], count = 0 }) {
  // Read-only use of Flow's planner: Daily Curated owns its recipe score and
  // persisted result, while Flow retains all queue, plan, and learning state.
  const remaining = candidates.slice();
  const selected = [];
  let previous = currentTrack() || null;
  while (remaining.length && selected.length < count) {
    const context = flowScoreContext(remaining.map((candidate) => candidate.track), previous || remaining[0].track, 'deep-library');
    const scored = [];
    for (let start = 0; start < remaining.length; start += DAILY_CURATED_SCORE_SLICE) {
      for (const candidate of remaining.slice(start, start + DAILY_CURATED_SCORE_SLICE)) {
        scored.push({ candidate, flow: scoreFlowCandidate(candidate.track, context) });
      }
      yield;
    }
    const planned = flowShufflePlanner.planSession({
      current: flowPlannerTrack(previous || scored[0].candidate.track, 0),
      candidates: scored.map((item) => flowPlannerTrack(item.candidate.track, item.flow.score + item.candidate.score)),
      baseScores: Object.fromEntries(scored.map((item) => [item.candidate.track.id, item.flow.score + item.candidate.score])),
      horizon: Math.min(10, Math.max(5, count - selected.length)),
      shape: 'wave',
      albumPolicy: 'track',
      preserveAlbumRuns: false,
    });
    const nextIds = planned.ids.filter((id) => remaining.some((candidate) => candidate.track.id === id));
    const batch = nextIds.length ? nextIds : [remaining[0].track.id];
    batch.forEach((id) => {
      if (selected.length >= count || selected.includes(id)) return;
      selected.push(id);
      const chosen = remaining.find((candidate) => candidate.track.id === id);
      if (chosen) previous = chosen.track;
    });
    const selectedSet = new Set(selected);
    for (let index = remaining.length - 1; index >= 0; index -= 1) {
      if (selectedSet.has(remaining[index].track.id)) remaining.splice(index, 1);
    }
    yield;
  }
  return selected;
}
function dailyCuratedPlanAdapter(request) {
  const steps = dailyCuratedPlanSteps(request);
  let step = steps.next();
  while (!step.done) step = steps.next();
  return step.value;
}

function emptyDailyMix() {
  const dateKey = dailyCurated.dayKey();
  return {
    id: `${DAILY_CURATED_COLLECTION_ID}:${dateKey}`,
    dateKey,
    recipeKey: DAILY_CURATED_RECIPE,
    trackIds: [],
    savedPlaylistId: '',
    explanationReceipt: {
      summary: 'Import local music to generate a Rediscovery mix. Daily Curated never fills the gap with cloud catalog tracks.',
      source: 'local-library',
      signals: ['Local library availability'],
      trackCount: 0,
      totalDurationSeconds: 0,
      metadataCoverage: 0,
      unfamiliarCount: 0,
      returningCount: 0,
      trackReasons: {},
    },
    artworkRecipe: { kind: 'local-spectrum', accentIndex: 0 },
  };
}

// A new day's mix is built after the app is up and the person is not typing,
// scrolling or clicking, a slice at a time. Until it lands the rail entry and
// panel say it is being prepared; nothing is guessed or shown in the meantime.
let dailyMixGeneration = null;
function pendingDailyMix() {
  const mix = emptyDailyMix();
  mix.pending = true;
  mix.explanationReceipt.summary = "Preparing today's listen from your library.";
  return mix;
}
function dailyMixOptions() {
  return { tracks: state.tracks, history: state.history, favorites: state.favorites, trackStats: state.signalJournal.trackStats };
}
function dailyMixQuietTurn() {
  return whenReadinessSettled().then(() => new Promise((resolve) => {
    const wait = () => scheduleIdleWork(() => {
      if (inputIsRecent()) setTimeout(wait, INTERACTION_QUIET_MS);
      else resolve();
    }, 1500);
    wait();
  }));
}
// Between slices: hand the frame back, and wait out any input in progress.
const DAILY_MIX_SLICE_MS = 10;
function dailyMixBreathe() {
  if (inputIsRecent()) return dailyMixQuietTurn();
  return new Promise((resolve) => setTimeout(resolve, 0));
}
function scheduleDailyMixGeneration() {
  if (dailyMixGeneration) return dailyMixGeneration;
  dailyMixGeneration = (async () => {
    try {
      await dailyMixQuietTurn();
      for (let attempt = 0; attempt < 3; attempt += 1) {
        if (dailyCurated.todaysMix(state.dailyMixes)) return;
        if (!state.tracks.some((track) => track?.id && !track.missing)) return;
        const options = dailyMixOptions();
        const prepared = dailyCurated.prepareRediscovery(options);
        let plannedIds = [];
        try {
          const steps = dailyCuratedPlanSteps({ candidates: prepared.candidates, count: prepared.count });
          let sliceStart = performance.now();
          let step = steps.next();
          while (!step.done) {
            if (performance.now() - sliceStart >= DAILY_MIX_SLICE_MS) { await dailyMixBreathe(); sliceStart = performance.now(); }
            step = steps.next();
          }
          plannedIds = step.value;
        } catch (error) {
          // The ranked order is the recipe's own; only Flow's smoothing is lost.
          console.warn('Pixelody Daily Curated planning failed; using the ranked order.', error);
        }
        // Importing or removing music, or midnight, while planning invalidates the plan.
        if (dailyCurated.libraryFingerprint(state.tracks) !== prepared.fingerprint || dailyCurated.dayKey() !== prepared.currentDay) continue;
        state.dailyMixes = dailyCurated.storeMix(state.dailyMixes, dailyCurated.finishRediscovery(options, prepared, plannedIds)).state;
        persist();
        renderTracks({ preserveOrder: true });
        return;
      }
    } catch (error) {
      console.warn('Pixelody Daily Curated could not prepare the daily listen.', error);
    } finally {
      dailyMixGeneration = null;
    }
  })();
  return dailyMixGeneration;
}
function dailyMixForToday() {
  if (!state.tracks.some((track) => track?.id && !track.missing)) return emptyDailyMix();
  const existing = dailyCurated.todaysMix(state.dailyMixes);
  if (existing) return existing;
  void scheduleDailyMixGeneration();
  return pendingDailyMix();
}

function dailyCuratedCollection() {
  const mix = dailyMixForToday();
  return {
    id: DAILY_CURATED_COLLECTION_ID,
    name: "Today's Listen",
    description: 'One ready path through music you own. Press play; it stays in this order until tomorrow.',
    trackIds: mix.trackIds,
    virtual: true,
    dailyMix: true,
    collectionType: 'Daily Curated',
    glyph: 'D',
    mix,
  };
}

function playlistTracks() {
  const playlist = activePlaylist();
  if (playlist.id === 'all') return state.tracks;
  if (playlist.id === 'recent') return [...new Set(state.history.map((entry) => entry.id))].map(trackById).filter(Boolean);
  if (playlist.id === 'favorites') return state.favorites.map(trackById).filter(Boolean);
  if (playlist.dailyMix) return playlist.trackIds.map(trackById).filter(Boolean);
  const ids = new Set(playlist.trackIds);
  return state.tracks.filter((track) => ids.has(track.id));
}
// These take a collection id, not activePlaylist(): an album view rebuilds its
// track list on every activePlaylist() call, and renderTracks asks often.
function isAlbumCollection(playlistId = state.activePlaylistId) {
  return String(playlistId || '').startsWith('album:');
}
function isUserPlaylist(playlistId = state.activePlaylistId) {
  return playlistId !== 'all' && state.playlists.some((item) => item.id === playlistId && !item.dailyMix);
}
// User playlists and albums have a natural order worth showing; library-wide
// views, smart collections and daily mixes do not offer one to choose.
function isOrderedCollection(playlistId = state.activePlaylistId) {
  return isUserPlaylist(playlistId) || isAlbumCollection(playlistId);
}
function activeSortKey() {
  if (isAlbumCollection()) return state.albumSort || 'playlist-order';
  if (isUserPlaylist()) return state.playlistSort || 'playlist-order';
  return state.sort === 'playlist-order' ? 'added-desc' : state.sort;
}
function setActiveSort(value) {
  if (isAlbumCollection()) state.albumSort = value;
  else if (isUserPlaylist()) state.playlistSort = value;
  else if (value !== 'playlist-order') state.sort = value;
}
function syncSortControl() {
  const select = $('#sortSelect');
  if (!select) return;
  const orderOption = select.querySelector('option[value="playlist-order"]');
  const ordered = isOrderedCollection();
  if (orderOption) { orderOption.hidden = !ordered; orderOption.disabled = !ordered; }
  syncQuestInventoryLabels();
  select.value = activeSortKey();
}
function collectionOrderComparator(playlist = activePlaylist()) {
  const number = (value, missing) => (Number.isFinite(Number(value)) && Number(value) > 0 ? Number(value) : missing);
  if (isAlbumCollection(playlist?.id)) {
    // A missing disc number means a single-disc album (disc 1); a missing
    // track number sorts after the numbered tracks on its disc.
    return (a, b) => number(a.discNumber, 1) - number(b.discNumber, 1)
      || number(a.trackNumber, Number.MAX_SAFE_INTEGER) - number(b.trackNumber, Number.MAX_SAFE_INTEGER)
      || String(a.title || '').localeCompare(String(b.title || ''));
  }
  const position = new Map(playlistTrackIds(playlist).map((id, index) => [id, index]));
  const last = Number.MAX_SAFE_INTEGER;
  return (a, b) => (position.has(a.id) ? position.get(a.id) : last) - (position.has(b.id) ? position.get(b.id) : last);
}
function visibleTracks() {
  const query = $('#search').value.trim().toLowerCase();
  const tracks = playlistTracks().filter((track) => {
    const matchesSearch = !query || `${track.title} ${track.artist} ${track.album || ''} ${track.genre || ''} ${track.composer || ''}`.toLowerCase().includes(query);
    const matchesFilter = state.filter === 'all' || state.filter === 'lossless' && isLossless(track) || state.filter === 'hires' && isHiRes(track);
    return matchesSearch && matchesFilter;
  });
  const text = (value) => String(value || '').toLocaleLowerCase();
  const quality = (track) => (track.sampleRate || 0) * (track.bitDepth || 0);
  const comparators = {
    'added-desc': (a, b) => (b.dateAdded || 0) - (a.dateAdded || 0),
    'title-asc': (a, b) => text(a.title).localeCompare(text(b.title)),
    'artist-asc': (a, b) => text(a.artist).localeCompare(text(b.artist)),
    'album-asc': (a, b) => text(a.album).localeCompare(text(b.album)),
    'quality-desc': (a, b) => quality(b) - quality(a),
    'plays-desc': (a, b) => (state.playCounts[b.id] || 0) - (state.playCounts[a.id] || 0),
  };
  if (activePlaylist().dailyMix) return tracks;
  const sortKey = activeSortKey();
  const comparator = sortKey === 'playlist-order' ? collectionOrderComparator() : comparators[sortKey];
  return tracks.sort(comparator || comparators['added-desc']);
}
function tracksInActiveShuffleOrder(tracks) {
  if (!state.shuffle || !state.flowShuffle.plan || !tracks.length) return tracks;
  const sourceIds = new Set(state.flowShuffle.plan.sourceQueueIds || []);
  if (!tracks.every((track) => sourceIds.has(track.id))) return tracks;
  const tracksById = new Map(tracks.map((track) => [track.id, track]));
  return flowShuffleEngine.displayOrder(state.flowShuffle, tracks.map((track) => track.id)).map((id) => tracksById.get(id)).filter(Boolean);
}
function preserveCurrentTrackRowOrder(tracks) {
  // The order last handed to the track browser rather than the rows in the
  // DOM: the list materializes rows on demand, so a large library has only
  // its first rows in the DOM.
  const order = new Map(trackBrowserTrackOrder.map((track, index) => [track.id, index]));
  if (!order.size) return tracks;
  const end = Number.MAX_SAFE_INTEGER;
  return tracks
    .map((track, index) => ({ track, index, order: order.has(track.id) ? order.get(track.id) : end }))
    .sort((a, b) => a.order - b.order || a.index - b.index)
    .map((item) => item.track);
}
function groupedLibraryCollections(mode) {
  if (mode === 'smart') return smartCollections();
  const groups = new Map();
  state.tracks.forEach((track) => {
    const name = collectionName(track, mode);
    if (!groups.has(name)) groups.set(name, { name, trackIds: [], background: null });
    const group = groups.get(name);
    group.trackIds.push(track.id);
    if (!group.background && track.artworkPath) group.background = track.artworkPath;
  });
  const prefix = mode === 'albums' ? 'album:' : 'artist:';
  const type = mode === 'albums' ? 'Album' : 'Artist';
  return [...groups.values()].sort((a, b) => a.name.localeCompare(b.name)).map((group) => {
    const id = `${prefix}${encodeURIComponent(group.name)}`;
    return { ...group, id, background: Object.prototype.hasOwnProperty.call(state.collectionBackgrounds, id) ? state.collectionBackgrounds[id] : group.background, virtual: true, collectionType: type, glyph: group.name.charAt(0).toUpperCase() };
  });
}
function playlistTrackIds(playlist) {
  if (playlist?.id === 'all') return state.tracks.map((track) => track.id);
  return (playlist?.trackIds || []).map((entry) => typeof entry === 'object' ? entry.id : entry).filter(Boolean);
}
function questSaveSlotMeta(playlist, index) {
  const ids = playlistTrackIds(playlist);
  const idSet = new Set(ids);
  const plays = ids.reduce((total, id) => total + (state.playCounts[id] || 0), 0);
  const lastHistory = state.history.find((entry) => idSet.has(entry.id));
  const lastPlayed = lastHistory?.playedAt ? timeAgo(lastHistory.playedAt) : 'Never played';
  const type = playlist.collectionType || (playlist.virtual ? 'Smart collection' : 'Playlist');
  const slot = playlist.id === 'favorites' ? 'FAV'
    : playlist.id === 'recent' ? 'REC'
      : playlist.dailyMix ? 'DLY'
      : playlist.id?.startsWith('smart:') ? 'CPU'
        : String(index + 1).padStart(2, '0');
  const award = playlist.id === 'favorites' ? { label: 'FAVORITE SAVE', kind: 'favorite' }
    : playlist.id === 'recent' ? { label: 'RUN LOG', kind: 'recent' }
      : plays >= 100 ? { label: 'MARATHON FILE', kind: 'marathon' }
        : ids.length >= 40 ? { label: 'FULL SHELF', kind: 'full' }
          : ids.length > 0 && ids.length <= 5 ? { label: 'TINY CART', kind: 'tiny' }
            : plays >= 25 ? { label: 'HOT SLOT', kind: 'hot' }
              : null;
  return {
    slot,
    type,
    count: playlist.id === 'all' ? state.tracks.length : ids.length,
    plays,
    lastPlayed,
    award,
  };
}
function activeCollectionIndex(playlist) {
  const collections = state.libraryMode === 'playlists' ? [
    dailyCuratedCollection(),
    { id: 'favorites' },
    { id: 'recent' },
    ...state.playlists,
  ] : groupedLibraryCollections(state.libraryMode);
  const index = collections.findIndex((collection) => collection.id === playlist?.id);
  return index >= 0 ? index : 0;
}
function questCollectionDurationText(seconds) {
  if (!Number.isFinite(seconds) || seconds <= 0) return '--';
  const totalMinutes = Math.round(seconds / 60);
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  return hours ? `${hours}H ${String(minutes).padStart(2, '0')}M` : `${minutes}M`;
}
function themeGlyphSeed(...parts) {
  return parts.map((part) => String(part ?? '')).join('|');
}
function themeGlyphAttributes(seed) {
  const glyph = themeGlyphDomain.describe(seed);
  return `data-theme-glyph="${glyph.variant}" data-theme-rotation="${glyph.rotation}" data-theme-edition="${glyph.edition}"`;
}
function applyThemeGlyph(element, seed) {
  if (!element) return null;
  const glyph = themeGlyphDomain.describe(seed);
  element.dataset.themeGlyph = String(glyph.variant);
  element.dataset.themeRotation = String(glyph.rotation);
  element.dataset.themeEdition = String(glyph.edition);
  return glyph;
}
function renderPlaylists() {
  const collections = state.libraryMode === 'playlists' ? [
    dailyCuratedCollection(),
    { id: 'favorites', name: 'Favorites', trackIds: state.favorites, background: state.collectionBackgrounds.favorites || null, virtual: true, glyph: 'F' },
    { id: 'recent', name: 'Recently Played', trackIds: state.history, background: state.collectionBackgrounds.recent || null, virtual: true, glyph: 'R' },
    ...state.playlists,
  ] : groupedLibraryCollections(state.libraryMode);
  document.querySelectorAll('[data-library-mode]').forEach((button) => {
    const active = button.dataset.libraryMode === state.libraryMode;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', String(active));
  });
  if (!collections.length) {
    const modeLabel = state.libraryMode === 'albums' ? 'album' : state.libraryMode === 'artists' ? 'artist' : 'track';
    $('#playlistList').innerHTML = cartridgeQuestExperienceActive()
      ? `<div class="rail-empty"><strong>No ${modeLabel} carts</strong><span>Load music with ${modeLabel} metadata to fill this rack.</span></div>`
      : `<div class="rail-empty">Import music with ${modeLabel} metadata to browse it here.</div>`;
    return;
  }
  const nextPlaylistHtml = collections.map((playlist, index) => {
    const save = questSaveSlotMeta(playlist, index);
    const count = save.count;
    const image = playlist.background ? `style="background-image:url('${escapeHtml(window.desktop.fileUrl(playlist.background))}')"` : '';
    const glyphAttributes = themeGlyphAttributes(themeGlyphSeed(playlist.id, playlist.name));
    const award = save.award ? `<span class="quest-collection-award" data-quest-award="${escapeHtml(save.award.kind)}">${escapeHtml(save.award.label)}</span>` : '';
    const dailyThumb = playlist.dailyMix ? '<span class="daily-curated-rail-mark" aria-hidden="true">D</span>' : '';
    const active = playlist.id === state.activePlaylistId;
    if (playlist.dailyMix) {
      const mixDate = dailyMixLocalDate(playlist.mix.dateKey);
      const compactDate = new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric' }).format(mixDate).toUpperCase();
      const availableCount = playlist.trackIds.map(trackById).filter((track) => track && !track.missing).length;
      const status = playlist.mix.pending ? "Preparing today's listen" : availableCount ? `${availableCount} local track${availableCount === 1 ? '' : 's'} · ready` : 'Add local music to begin';
      return `<button class="playlist-item daily-curated-entry ${active ? 'active' : ''}" data-playlist="${playlist.id}" aria-current="${active ? 'page' : 'false'}" aria-label="Today's listen: Rediscovery, ${escapeHtml(status)}" title="Today's listen · no setup · ready until tomorrow" data-daily-curated="true"><span class="playlist-thumb" ${glyphAttributes}>${dailyThumb}</span><span class="playlist-copy"><span class="daily-curated-entry-eyebrow">DAILY CURATED <time datetime="${escapeHtml(playlist.mix.dateKey)}">${escapeHtml(compactDate)}</time></span><strong>Today's Listen</strong><span class="daily-curated-entry-promise">One ready path. No setup.</span><span class="daily-curated-entry-status"><i aria-hidden="true"></i>${escapeHtml(status)}</span></span><span class="playlist-dots" aria-hidden="true">›</span></button>`;
    }
    return `<button class="playlist-item ${active ? 'active' : ''}" data-playlist="${playlist.id}" data-quest-slot="${escapeHtml(save.slot)}"${loFiCafeCardAttributes(playlist, save)} aria-current="${active ? 'page' : 'false'}" title="${escapeHtml(playlist.name)}" ${playlist.dailyMix ? 'data-daily-curated="true"' : ''}><span class="playlist-thumb" ${glyphAttributes} ${image}>${playlist.dailyMix ? dailyThumb : playlist.background ? '' : escapeHtml(playlist.glyph || playlist.name.charAt(0).toUpperCase())}</span><span class="playlist-copy"><span class="quest-save-slot">SLOT ${escapeHtml(save.slot)} <b>${escapeHtml(save.type.toUpperCase())}</b></span><strong>${escapeHtml(playlist.name)}</strong><span>${playlist.dailyMix ? 'Today · Rediscovery' : `${save.type} &middot; ${count} track${count === 1 ? '' : 's'}`}</span><span class="quest-save-meta">${collectionWearText(playlist, save)}</span>${award}</span><span class="playlist-dots">${playlist.virtual ? '' : '...'}</span></button>`;
  }).join('');
  if ($('#playlistList').innerHTML !== nextPlaylistHtml) $('#playlistList').innerHTML = nextPlaylistHtml;
}
function collectionArtworkFor(playlist = activePlaylist()) {
  if (playlist.dailyMix) return null;
  // Explicit null is a durable request for theme artwork, not an absent override.
  if (playlist.virtual && Object.prototype.hasOwnProperty.call(state.collectionBackgrounds, playlist.id) && state.collectionBackgrounds[playlist.id] === null) return null;
  return playlist.background || (playlist.collectionType ? playlistTracks().find((track) => track.artworkPath)?.artworkPath : null);
}

function renderHero() {
  const playlist = activePlaylist(); const count = playlistTracks().length;
  const isDailyMix = Boolean(playlist.dailyMix);
  $('#playlistTitle').textContent = playlist.name;
  $('#playlistTitle').dataset.tideplotDisplayTitle = playlist.name;
  const collectionType = playlist.collectionType || (playlist.virtual ? 'Smart collection' : 'Playlist');
  $('#collectionType').textContent = collectionType.toUpperCase();
  $('#playlistMeta').textContent = `${count} track${count === 1 ? '' : 's'} · ${playlist.collectionType || (playlist.virtual ? 'Smart collection' : 'Local playlist')}`;
  const descriptions = { all: 'Your private, uncompromised listening library.', favorites: 'The tracks you never want to lose.', recent: 'A chronological trail of your listening.' };
  $('#playlistDescription').textContent = playlist.description || descriptions[playlist.id] || (playlist.collectionType === 'Album' ? 'Every track from this album, gathered automatically.' : playlist.collectionType === 'Artist' ? 'Every track by this artist in your local library.' : 'A personal collection tuned your way.');
  const hero = $('#playlistHero'); const cover = $('#playlistCover');
  const artwork = collectionArtworkFor(playlist);
  hero.dataset.dailyCurated = String(isDailyMix);
  cover.classList.toggle('has-image', Boolean(artwork));
  $('#backgroundButton').classList.toggle('hidden', isDailyMix);
  syncBackgroundCabinet();
  $('#playlistMore').classList.toggle('hidden', isDailyMix || !state.playlists.some((item) => item.id === playlist.id));
  if (artwork) {
    const url = window.desktop.fileUrl(artwork);
    const artCss = `url("${url}")`;
    if (hero.style.getPropertyValue('--playlist-art') !== artCss) hero.style.setProperty('--playlist-art', artCss);
    if (!hero.classList.contains('has-artwork')) hero.classList.add('has-artwork');
    const heroBg = appearance.theme === 'crystal' ? '' : artCss;
    if (hero.style.backgroundImage !== heroBg) hero.style.backgroundImage = heroBg;
    if (cover.style.backgroundImage !== artCss) cover.style.backgroundImage = artCss;
    if (!cover.querySelector('.signal-orbit-ring')) cover.innerHTML = signalOrbitMarkup;
  } else {
    hero.style.removeProperty('--playlist-art');
    hero.classList.remove('has-artwork');
    if (hero.style.backgroundImage !== '') hero.style.backgroundImage = '';
    if (cover.style.backgroundImage !== '') cover.style.backgroundImage = '';
    const desiredHtml = `${signalOrbitMarkup}<span>${isDailyMix ? 'D' : escapeHtml(playlist.name.charAt(0).toUpperCase())}</span>`;
    if (cover.innerHTML !== desiredHtml) cover.innerHTML = desiredHtml;
  }
  applyThemeGlyph(cover, themeGlyphSeed(playlist.id, playlist.name));
  syncQuestRareCue();
  syncQuestBootMessage();
  syncQuestCollectionPanel();
  syncQuestMiniMap();
  syncQuestAchievementShelf();
  syncGhostIndexUi();
  syncVioletHardware();
  syncHarmonicRegistryUi();
}

function renderDailyCuratedPanel() {
  const panel = $('#dailyCuratedPanel');
  if (!panel) return;
  const playlist = activePlaylist();
  const isDailyMix = Boolean(playlist.dailyMix);
  panel.classList.toggle('hidden', !isDailyMix);
  document.body.classList.toggle('daily-curated-view', isDailyMix);
  $('.collection-body')?.classList.toggle('daily-curated-active', isDailyMix);
  $('#dailyCuratedSequence')?.classList.toggle('hidden', !isDailyMix);
  $('#dailyCuratedSequence')?.setAttribute('aria-hidden', String(!isDailyMix));
  $('#addToPlaylist').classList.toggle('hidden', isDailyMix);
  if (!isDailyMix) return;
  const mix = playlist.mix || dailyMixForToday();
  const tracks = playlistTracks();
  const availableTracks = tracks.filter((track) => !track.missing);
  const receipt = mix.explanationReceipt || {};
  const unavailable = Math.max(0, mix.trackIds.length - availableTracks.length);
  const unheard = Number(receipt.unfamiliarCount || 0);
  const returning = Number(receipt.returningCount || 0);
  const stateLabel = !mix.trackIds.length ? 'empty' : unavailable ? 'partial' : 'ready';
  const leadTrack = availableTracks[0] || null;
  panel.dataset.state = !mix.trackIds.length ? 'empty' : unavailable ? 'partial' : 'ready';
  panel.dataset.recipe = mix.recipeKey || DAILY_CURATED_RECIPE;
  setText('#dailyCuratedTitle', 'Rediscovery');
  setText('#dailyCuratedDayNumber', String(dailyMixLocalDate(mix.dateKey).getDate()).padStart(2, '0'));
  setText('#dailyCuratedDate', `${dailyMixDateLabel(mix.dateKey)} · Set for the day. A new listen arrives tomorrow.`);
  if (mix.pending) panel.dataset.state = 'pending';
  setText('#dailyCuratedReadyMark', mix.pending ? 'PREPARING' : stateLabel === 'empty' ? 'WAITING FOR MUSIC' : unavailable ? `${unavailable} UNAVAILABLE` : 'READY TODAY');
  setText('#dailyCuratedPromise', mix.pending
    ? "Preparing today's listen. You can keep using Pixelody; it will appear here in a moment."
    : stateLabel === 'empty'
    ? 'Bring in music once and Daily Curated will prepare a simple listening path from your own library.'
    : 'A ready-to-play path through music you own. No setup, no choices to configure, and no reshuffle until tomorrow.');
  setText('#dailyCuratedLeadTitle', leadTrack?.title || (mix.pending ? "Preparing today's listen" : mix.trackIds.length ? "Today's tracks are unavailable" : 'Waiting for local music'));
  setText('#dailyCuratedLeadMeta', leadTrack ? `${leadTrack.artist || 'Unknown artist'}${leadTrack.album ? ` · ${leadTrack.album}` : ''}` : mix.trackIds.length ? 'The missing tracks stay recorded instead of being silently replaced.' : "Import music and tomorrow's path takes care of itself.");
  setText('#dailyCuratedTrackCount', unavailable ? `${availableTracks.length} of ${mix.trackIds.length}` : String(availableTracks.length));
  setText('#dailyCuratedDuration', dailyMixDurationText(receipt.totalDurationSeconds));
  setText('#dailyCuratedUnheard', String(unheard));
  setText('#dailyCuratedReturning', String(returning));
  setText('#dailyCuratedCoverage', `Track information coverage: ${receipt.metadataCoverage || 0}%`);
  const shape = unheard && returning
    ? `${unheard} you have not played yet, balanced with ${returning} worth hearing again.`
    : unheard
      ? `${unheard} tracks from your library that you have not played yet.`
      : returning
        ? `${returning} tracks that have been waiting for another listen.`
        : receipt.summary || 'Built from music on this device.';
  setText('#dailyCuratedSummary', `${shape}${unavailable ? ` ${unavailable} unavailable track${unavailable === 1 ? ' remains' : 's remain'} visible in today's record.` : ''}`);
  setText('#dailyCuratedSource', 'Made privately from this device: local listening history, favorites, and musical flow. No account, cloud catalog, or J.A.M. session data.');
  setText('#dailyCuratedSequenceLabel', mix.trackIds.length ? `${mix.trackIds.length} track${mix.trackIds.length === 1 ? '' : 's'} · play follows this order.` : 'Your listening order will appear here.');
  $('#trackTable')?.setAttribute('aria-label', isDailyMix ? "Today's listening order" : 'Tracks');
  const reasons = $('#dailyCuratedReasons');
  const reasonById = receipt.trackReasons || {};
  reasons.innerHTML = tracks.slice(0, 8).map((track) => `<li><b>${escapeHtml(track.title || 'Untitled track')}</b> — ${escapeHtml(track.missing ? 'Source file unavailable; kept in today\'s record' : reasonById[track.id] || 'Part of today\'s local listening path')}</li>`).join('') || '<li>Import local music to build this listen.</li>';
  const saveButton = $('#dailyCuratedSave');
  const savedPlaylist = mix.savedPlaylistId && state.playlists.find((item) => item.id === mix.savedPlaylistId);
  const alreadySaved = Boolean(savedPlaylist);
  saveButton.disabled = !mix.trackIds.length;
  saveButton.textContent = alreadySaved ? 'Kept in Library' : 'Keep this day';
  setText('#dailyCuratedSaveHint', alreadySaved ? `Saved as ${savedPlaylist.name}. It is now an ordinary editable playlist.` : "Makes a normal, editable playlist. Today's listen stays unchanged.");
  $('#dailyCuratedPlay').disabled = !availableTracks.length;
  $('#dailyCuratedPlay').setAttribute('aria-label', availableTracks.length ? `Start today's listen with ${leadTrack.title} by ${leadTrack.artist || 'Unknown artist'}` : "Today's listen is unavailable");
}

function syncHarmonicRegistryUi() {
  const playlist = activePlaylist();
  const tracks = playlistTracks();
  const track = currentTrack();
  const isLive = Boolean(track && !audio.paused);
  const glyph = applyThemeGlyph($('#playlistCover'), themeGlyphSeed(playlist?.id, playlist?.name));
  applyThemeGlyph($('#miniCover'), themeGlyphSeed(track?.id, track?.title, track?.artist));
  const rate = Number(track?.sampleRate) > 0 ? `${(Number(track.sampleRate) / 1000).toFixed(Number(track.sampleRate) % 1000 ? 1 : 0)} KHZ` : '--';
  const depth = Number(track?.bitDepth) > 0 ? `${Number(track.bitDepth)}-BIT` : '--';
  const output = meaningfulOutputLabel(outputState.activeLabel || outputState.preferredLabel || 'System Default');
  setText('#hrTrackCount', String(tracks.length).padStart(2, '0'));
  setText('#hrSource', track ? String(track.format || 'LOCAL').toUpperCase().slice(0, 12) : 'LOCAL');
  setText('#hrDepthRate', `${depth} / ${rate}`);
  setText('#hrOutput', String(output || 'System Default').toUpperCase().replace(/\s+/g, ' ').slice(0, 24));
  setText('#hrMissingArt', String(tracks.filter((item) => !item.artworkPath).length).padStart(2, '0'));
  setText('#hrEditionMark', `ED. ${String((glyph?.edition || 0) + 1).padStart(2, '0')}`);
  setText('#hrPlayerState', isLive ? 'LIVE / CONFIRMED' : track ? 'READY / PAUSED' : 'READY');
  setText('#hrPlayerFormat', track ? String(track.format || 'LOCAL').toUpperCase().slice(0, 12) : 'LOCAL');
  setText('#hrPlayerQueue', String(activeQueue().length).padStart(2, '0'));
  document.body.dataset.harmonicState = isLive ? 'live' : track ? 'ready' : tracks.length ? 'indexed' : 'empty';
}

function syncVioletHardware(displayTracks = visibleTracks()) {
  const tracks = displayTracks;
  const track = currentTrack();
  const index = track ? tracks.findIndex((item) => item.id === track.id) : -1;
  const isLive = Boolean(track && !audio.paused);
  const outputLabel = meaningfulOutputLabel(outputState.activeLabel || outputState.preferredLabel || 'System Default');
  const compactOutput = String(outputLabel || 'System Default').toUpperCase().replace(/\s+/g, ' ').slice(0, 18);
  const source = track ? String(track.format || 'LOCAL').toUpperCase().slice(0, 10) : 'LOCAL';
  const position = `${String(index >= 0 ? index + 1 : 0).padStart(2, '0')}/${String(tracks.length).padStart(2, '0')}`;
  setText('#violetHeroCount', String(tracks.length).padStart(2, '0'));
  setText('#violetHeroPosition', position);
  setText('#violetHeroState', isLive ? 'SIGNAL LIVE' : track ? 'FOCUS READY' : tracks.length ? 'INDEX READY' : 'EMPTY');
  setText('#violetHeroRoute', isLive ? 'OUTPUT CONFIRMED' : 'OUTPUT READY');
  setText('#violetPlayerSource', source);
  setText('#violetPlayerTransport', isLive ? 'SIGNAL LIVE' : track ? 'PAUSED' : 'READY');
  setText('#violetPlayerOutput', compactOutput);
  document.body.dataset.violetState = isLive ? 'live' : track ? 'ready' : tracks.length ? 'indexed' : 'empty';
}

function syncGhostIndexUi(displayTracks = visibleTracks()) {
  const tracks = displayTracks;
  const activeTrack = currentTrack();
  const activeIndex = activeTrack ? tracks.findIndex((track) => track.id === activeTrack.id) : -1;
  const currentNumber = activeIndex >= 0 ? activeIndex + 1 : 0;
  const total = tracks.length;
  const isLive = Boolean(activeTrack && !audio.paused);
  const depth = total > 1 && activeIndex >= 0 ? Math.round((activeIndex / (total - 1)) * 100) : 0;
  const eventLabel = `${String(currentNumber).padStart(2, '0')}/${String(total).padStart(2, '0')}`;
  const access = isLive ? 'r-x LIVE' : activeTrack ? 'r-- READY' : 'r-- EMPTY';
  setText('#ghostFieldCurrent', String(currentNumber).padStart(2, '0'));
  setText('#ghostFieldTotal', String(total).padStart(2, '0'));
  setText('#ghostFieldState', isLive ? 'RESOLVING' : activeTrack ? 'STANDBY' : 'UNMAPPED');
  setText('#ghostAccess', access);
  setText('#ghostRecordCount', String(total).padStart(2, '0'));
  setText('#ghostDepth', `${String(depth).padStart(2, '0')}%`);
  setText('#ghostPlayerEvent', eventLabel);
  setText('#ghostPlayerAccess', access);
  setText('#ghostPlayerField', activeTrack ? String(activeTrack.format || 'LOCAL').toUpperCase().slice(0, 10) : 'LOCAL');
  document.body.dataset.ghostField = isLive ? 'live' : activeTrack ? 'ready' : 'empty';
}

function syncQuestCollectionPanel() {
  if (!cartridgeQuestExperienceActive()) return;
  const panel = $('#questCollectionPanel');
  if (!panel) return;
  const playlist = activePlaylist();
  const tracks = playlistTracks();
  const save = questSaveSlotMeta(playlist, activeCollectionIndex(playlist));
  const totalSeconds = tracks.reduce((total, track) => total + (Number(track.duration) || 0), 0);
  const idSet = new Set(tracks.map((track) => track.id));
  const lastHistory = state.history.find((entry) => idSet.has(entry.id));
  const current = currentTrack();
  const currentIndex = current ? tracks.findIndex((track) => track.id === current.id) : -1;
  const hiResCount = tracks.filter(isHiRes).length;
  const losslessCount = tracks.filter((track) => isLossless(track) || isHiRes(track)).length;
  const qualityLabel = hiResCount ? `${hiResCount} RARE` : losslessCount ? `${losslessCount} LOOT` : tracks.length ? 'STD CARTS' : 'EMPTY';
  const status = currentIndex >= 0
    ? `STAGE ${currentIndex + 1}/${tracks.length || 1}`
    : tracks.length
      ? qualityLabel
      : 'EMPTY';
  panel.dataset.questAward = save.award?.kind || '';
  setText('#questCollectionSlot', `${save.slot} / ${save.type.toUpperCase()}`);
  setText('#questCollectionCount', `${tracks.length}`);
  setText('#questCollectionTime', questCollectionDurationText(totalSeconds));
  setText('#questCollectionPlays', questScoreText(save.plays));
  setText('#questCollectionLast', (lastHistory?.playedAt ? timeAgo(lastHistory.playedAt) : 'Never').toUpperCase());
  setText('#questCollectionStatus', status);
  setText('#questCollectionSummary', `${save.slot} / ${tracks.length} CART${tracks.length === 1 ? '' : 'S'} / ${status}`);
}

function syncQuestMiniMap() {
  if (!cartridgeQuestExperienceActive()) return;
  const map = $('#questMiniMap');
  if (!map) return;
  const tracks = playlistTracks();
  const total = tracks.length;
  const track = currentTrack();
  const playlistIndex = track ? tracks.findIndex((item) => item.id === track.id) : -1;
  const activeIndex = playlistIndex >= 0 ? playlistIndex : 0;
  const trackDuration = Number.isFinite(audio.duration) && audio.duration > 0 ? audio.duration : Number(track?.duration) || 0;
  const trackProgress = trackDuration > 0 ? Math.max(0, Math.min(1, (Number(audio.currentTime) || 0) / trackDuration)) : 0;
  const collectionProgress = total > 1 && playlistIndex >= 0 ? (activeIndex + trackProgress) / total : total === 1 && playlistIndex >= 0 ? trackProgress : 0;
  const nodeIndex = total > 1 && playlistIndex >= 0 ? Math.round(activeIndex / Math.max(1, total - 1) * 6) : 0;
  map.style.setProperty('--quest-map-progress', `${Math.max(0, Math.min(1, collectionProgress)) * 100}%`);
  map.style.setProperty('--quest-map-node', String(Math.max(0, Math.min(6, nodeIndex))));
  map.classList.toggle('is-active', playlistIndex >= 0);
  map.classList.toggle('is-playing', playlistIndex >= 0 && !audio.paused);
  map.querySelectorAll('.quest-cabinet-body > i').forEach((node, index) => {
    node.classList.toggle('visited', playlistIndex >= 0 && index <= nodeIndex);
    node.classList.toggle('current', playlistIndex >= 0 && index === nodeIndex);
  });
  const label = $('#questMiniMapLabel');
  if (label) {
    if (!total) label.textContent = 'NO CART';
    else if (playlistIndex < 0) label.textContent = `${total} STAGE${total === 1 ? '' : 'S'}`;
    else label.textContent = `STAGE ${activeIndex + 1}/${total}`;
  }
  const mapSummary = $('#questMiniMapSummary');
  if (mapSummary) {
    if (!total) mapSummary.textContent = 'NO CART / ROUTE IDLE';
    else if (playlistIndex < 0) mapSummary.textContent = `${total} STAGES / READY`;
    else mapSummary.textContent = `STAGE ${activeIndex + 1} OF ${total} / ${Math.round(collectionProgress * 100)}%`;
  }
  syncQuestCollectionPanel();
}

