function addTracksToPlaylist(playlistId, trackIds) {
  const playlist = state.playlists.find((p) => p.id === playlistId);
  if (!playlist) return { added: 0, skipped: 0 };
  if (!Array.isArray(playlist.trackIds)) playlist.trackIds = [];
  const plan = libraryBatchDomain.planPlaylistAdd(playlist.trackIds, trackIds, (id) => Boolean(trackById(id)));
  if (!plan.added.length) return { added: 0, skipped: plan.skipped };
  playlist.trackIds.push(...plan.added);
  persist();
  renderPlaylists();
  if (state.activePlaylistId === playlist.id) renderTracks({ animateRows: true });
  return { added: plan.added.length, skipped: plan.skipped };
}
function toastPlaylistAdd(playlist, result) {
  if (!playlist) return;
  const skipped = result.skipped ? ` (${result.skipped} already there)` : '';
  if (!result.added) showToast(`Everything is already in ${playlist.name}.`);
  else showToast(`Added ${libraryBatchDomain.describeCount(result.added, 'track')} to ${playlist.name}${skipped}.`);
}
function addTrackToPlaylist(playlistId, trackId) {
  const playlist = state.playlists.find((p) => p.id === playlistId);
  if (playlistPickerBatchIds && playlist) {
    toastPlaylistAdd(playlist, addTracksToPlaylist(playlistId, playlistPickerBatchIds));
    closePlaylistPicker({ restoreFocus: true });
    return;
  }
  const track = trackById(trackId);
  if (!playlist || !track) return;
  if (!Array.isArray(playlist.trackIds)) playlist.trackIds = [];
  if (playlist.trackIds.includes(trackId)) {
    showToast(`"${track.title}" is already in ${playlist.name}.`);
    closePlaylistPicker({ restoreFocus: true });
    return;
  }
  playlist.trackIds.push(trackId);
  persist();
  renderPlaylists();
  if (state.activePlaylistId === playlist.id) renderTracks({ animateRows: true });
  showToast(`Added "${track.title}" to ${playlist.name}.`);
  closePlaylistPicker({ restoreFocus: true });
}
function confirmPlaylistPickerCreation() {
  const name = $('#newPlaylistPickerName')?.value.trim();
  const error = $('#playlistPickerError');
  if (!name) {
    if (error) { error.textContent = 'Enter a playlist name.'; error.classList.remove('hidden'); }
    $('#newPlaylistPickerName')?.focus();
    return;
  }
  if (state.playlists.some((p) => p.name.toLocaleLowerCase() === name.toLocaleLowerCase())) {
    if (error) { error.textContent = 'A playlist with that name already exists.'; error.classList.remove('hidden'); }
    $('#newPlaylistPickerName')?.select();
    return;
  }
  const track = trackById(playlistPickerTrackId);
  const batchIds = playlistPickerBatchIds ? [...new Set(playlistPickerBatchIds.filter((id) => trackById(id)))] : null;
  const playlist = {
    id: `playlist-${Date.now()}`,
    name,
    trackIds: batchIds || (playlistPickerTrackId ? [playlistPickerTrackId] : []),
    background: null,
  };
  state.playlists.push(playlist);
  persist();
  renderPlaylists();
  if (batchIds) showToast(`Created ${playlist.name} and added ${libraryBatchDomain.describeCount(batchIds.length, 'track')}.`);
  else if (track) showToast(`Created ${playlist.name} and added "${track.title}".`);
  else showToast(`Created ${playlist.name}.`);
  closePlaylistPicker({ restoreFocus: true });
}
function selectLibraryMode(mode) {
  state.libraryMode = mode;
  if (mode === 'playlists') {
    if (state.activePlaylistId.startsWith('album:') || state.activePlaylistId.startsWith('artist:') || state.activePlaylistId.startsWith('smart:')) state.activePlaylistId = 'all';
  } else {
    const first = groupedLibraryCollections(mode)[0];
    state.activePlaylistId = first ? first.id : 'all';
  }
  persist(); renderTracks({ animateRows: true }); triggerThemeAction('mode', mode);
}
// Export writes the playlist's saved order (All Music exports the library) as
// an M3U8 file other players and Pixelody's own importer can read.
async function exportPlaylist(id) {
  const playlist = state.playlists.find((item) => item.id === id);
  if (!playlist) return;
  const tracks = id === 'all' ? state.tracks.slice() : playlistTrackIds(playlist).map(trackById).filter(Boolean);
  if (!tracks.length) { showToast(`${playlist.name} is empty.`); return; }
  const entries = tracks.map((track) => ({
    path: track.path,
    title: String(track.title || '').slice(0, 1024),
    artist: String(track.artist || '').slice(0, 1024),
    duration: Number.isFinite(track.duration) ? track.duration : null,
  }));
  try {
    const result = await window.desktop.exportPlaylistM3u({ name: String(playlist.name || 'Playlist').slice(0, 256), entries });
    if (result?.ok) showToast(`Exported ${result.count} track${result.count === 1 ? '' : 's'} from ${playlist.name}.`);
    else if (result) showToast('Playlist export failed.');
  } catch {
    showToast('Playlist export failed.');
  }
}
function renamePlaylist(id) {
  const playlist = state.playlists.find((item) => item.id === id); if (!playlist) return;
  const name = prompt('Rename playlist:', playlist.name); if (!name?.trim()) return;
  playlist.name = name.trim(); persist(); renderTracks();
}
function deletePlaylist(id) {
  if (id === 'all') { showToast('All Music cannot be deleted.'); return; }
  const playlist = state.playlists.find((item) => item.id === id); if (!playlist || !confirm(`Delete "${playlist.name}"? Your music files will stay in All Music.`)) return;
  state.playlists = state.playlists.filter((item) => item.id !== id); state.activePlaylistId = 'all'; persist(); renderTracks();
}
function toggleFavorite(id) {
  state.favorites = state.favorites.includes(id) ? state.favorites.filter((trackId) => trackId !== id) : [...state.favorites, id];
  const favorite = state.favorites.includes(id);
  const track = trackById(id);
  if (favorite) questSessionFavoriteAdds += 1;
  recordSignalEvent('track_favorited', { trackId: id, favorite });
  syncQuestRareCue();
  persist(); renderTracks(); showToast(favorite ? 'Added to Favorites.' : 'Removed from Favorites.');
  questEncounterToast(favorite ? 'FAV ITEM' : 'ITEM DROPPED', track?.title || 'TRACK', favorite ? 'SAVED' : 'REMOVED');
}
function removeTrack(id) {
  if (activePlaylist().id === 'all' || activePlaylist().virtual) {
    state.tracks = state.tracks.filter((track) => track.id !== id);
    state.playlists.forEach((playlist) => playlist.trackIds = playlist.trackIds.filter((trackId) => trackId !== id));
    state.favorites = state.favorites.filter((trackId) => trackId !== id);
    state.history = state.history.filter((entry) => entry.id !== id);
    state.queue = state.queue.filter((trackId) => trackId !== id);
    delete state.signalJournal.trackStats[id];
    state.signalJournal.events = state.signalJournal.events.filter((event) => event.trackId !== id);
  } else activePlaylist().trackIds = activePlaylist().trackIds.filter((trackId) => trackId !== id);
  persistSignalJournal();
  persist(); renderTracks(); renderQueue();
}
function resetTrackSignal(id = currentTrack()?.id) {
  const track = trackById(id);
  if (!track) return;
  if (!confirm(`Reset Signal Journal stats for "${track.title}"? Local metadata and the music file stay unchanged.`)) return;
  delete state.signalJournal.trackStats[id];
  state.signalJournal.events = state.signalJournal.events.filter((event) => event.trackId !== id);
  if (state.signalJournal.lastSignal?.trackId === id) state.signalJournal.lastSignal = null;
  if (state.signalJournal.lastShuffle?.trackId === id) state.signalJournal.lastShuffle = null;
  if (state.flowShuffle.lastPick?.trackId === id) state.flowShuffle.lastPick = null;
  state.flowShuffle.history = state.flowShuffle.history.filter((trackId) => trackId !== id);
  state.flowShuffle.cycle = state.flowShuffle.cycle.filter((trackId) => trackId !== id);
  persistSignalJournal();
  persist();
  updateSignalMetadataFields(track);
  updateFlowShuffleUi();
  showToast('Track signal reset.');
}
