  diagnosticsState.outputMessage = message;
  diagnosticsState.outputError = error;
  diagnosticsState.toneRoute = outputState.activeLabel;
  $('#sideOutput').textContent = outputState.activeLabel;
  $('#topOutput').textContent = outputState.activeLabel;
