function markOutputChange(previousId, nextId) {
  if ((previousId || '') === (nextId || '')) return;
  diagnosticsState.outputChanges += 1;
  diagnosticsState.lastOutputChangeAt = new Date().toISOString();
}

async function routeOutput(deviceId = '', options = {}) {
  const targetId = deviceId || '';
  const targetLabel = selectedOutputLabel(targetId);
  const previousId = outputState.activeId || '';
  abortSpeakerRigValidation('Primary output changed before the physical run completed.', { quiet: true });
  if (!options.skipCalibrationRecovery) await abortActiveRigCalibration('Output route changed.', { restoreRoute: false, resumeMusic: true, blockedReason: 'Output route changed during calibration.' });
  stopCalibrationPreview();
  try {
    if (typeof audio.setSinkId !== 'function') {
      if (targetId) throw new Error('This runtime cannot route the primary media element to a specific output.');
    } else {
      await audio.setSinkId(targetId);
    }
    // Once the media element feeds the Web Audio graph, the graph's context owns the sink.
    if (state.context && typeof state.context.setSinkId === 'function') await routePrimaryGraphSink(targetId);
    const routedSinkId = typeof audio.sinkId === 'string' ? audio.sinkId : targetId;
    outputState.activeId = routedSinkId;
    outputState.activeLabel = targetLabel || 'System Default';
    markOutputChange(previousId, outputState.activeId);
    if (options.persistPreferred !== false) persistPreferredOutput(targetId, outputState.activeLabel);
    setOutputStatus('routed', targetId ? `Routed to ${outputState.activeLabel}` : 'System Default routed');
  } catch (error) {
    if (typeof audio.setSinkId === 'function') await audio.setSinkId('').catch(() => {});
    outputState.activeId = typeof audio.sinkId === 'string' ? audio.sinkId : '';
    outputState.activeLabel = selectedOutputLabel(outputState.activeId) || 'System Default';
    markOutputChange(previousId, outputState.activeId);
    const select = $('#outputSelect');
    if (select) select.value = outputState.activeId || '';
    setOutputStatus('error', `Output error: ${error.message}`, error.message);
  }
  syncEqControls();
  syncSpatialControls();
  renderDeviceProfileLibrary({ preferSuggestion: true });
  syncSecondarySpeakerOutputElements('primary-route-changed');
  renderSpeakerSystems();
  updateLatencyUi();
  updateMicCalibrationUi();
  applyEq();
  syncInterfaceSoundEngine();
  await syncTestToneOutputRoute();
}

async function refreshOutputs(options = {}) {
  const select = $('#outputSelect');
  const source = options.source || 'manual';
  const beforeRigAvailability = speakerRigAvailabilitySnapshot();
  if (!navigator.mediaDevices?.enumerateDevices) {
    outputState.devices = [];
    select.innerHTML = '<option value="">System Default</option>';
    await routeOutput('', { persistPreferred: false });
    setOutputStatus('unsupported', 'Output list unavailable; using System Default');
    recordSpeakerRigDeviceAvailabilityChange(beforeRigAvailability, speakerRigAvailabilitySnapshot(), source);
    return;
  }
  try {
    if (options.requestLabels !== false && !outputState.labelsUnlocked) {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        stream.getTracks().forEach((track) => track.stop());
        outputState.labelsUnlocked = true;
      } catch {
        outputState.labelsUnlocked = false;
      }
    }
    const devices = (await navigator.mediaDevices.enumerateDevices()).filter((device) => device.kind === 'audiooutput');
    outputState.devices = devices;
    reconcileSpeakerSystemMemberRoutes();
    recordSpeakerRigDeviceAvailabilityChange(beforeRigAvailability, speakerRigAvailabilitySnapshot(), source);
    select.innerHTML = `<option value="">System Default</option>${devices.map((device) => `<option value="${escapeHtml(device.deviceId)}">${escapeHtml(device.label || 'Audio output')}</option>`).join('')}`;
    const preferredAvailable = !outputState.preferredId || devices.some((device) => device.deviceId === outputState.preferredId);
    const nextId = preferredAvailable ? outputState.preferredId : '';
    select.value = nextId;
    await routeOutput(nextId, { persistPreferred: false });
    if (!preferredAvailable) setOutputStatus('missing', `${outputState.preferredLabel} unavailable; using System Default`);
    renderSpeakerSystems();
  } catch (error) {
    outputState.devices = [];
    select.innerHTML = '<option value="">System Default</option>';
    await routeOutput('', { persistPreferred: false });
    setOutputStatus('error', `Output scan error: ${error.message}`, error.message);
    recordSpeakerRigDeviceAvailabilityChange(beforeRigAvailability, speakerRigAvailabilitySnapshot(), source);
    renderSpeakerSystems();
  }
}

function installOutputDeviceWatcher() {
  if (!navigator.mediaDevices) return;
  let deviceChangeTimer = 0;
  const onDeviceChange = () => {
    clearTimeout(deviceChangeTimer);
    deviceChangeTimer = setTimeout(() => {
      deviceChangeTimer = 0;
      refreshOutputs({ requestLabels: false, source: 'devicechange' });
      refreshMicInputs({ requestLabels: false });
    }, 220);
  };
  if (navigator.mediaDevices.addEventListener) navigator.mediaDevices.addEventListener('devicechange', onDeviceChange);
  else navigator.mediaDevices.ondevicechange = onDeviceChange;
}

function prepareSurfaceForOpen(selector) {
  const element = $(selector);
  if (!element) return null;
  element.classList.remove('surface-prewarm');
  element.removeAttribute('data-prewarming');
  element.inert = false;
  element.removeAttribute('aria-hidden');
  return element;
}

// Resolves once the surface has been laid out (or was skipped), so callers can
// prewarm one at a time instead of laying out every hidden panel in one burst.
function prewarmSurface(selector, setup = null) {
  if (prewarmedSurfaces.has(selector)) return Promise.resolve();
  prewarmedSurfaces.add(selector);
  return new Promise((resolve) => {
    const attempt = () => {
      scheduleIdleWork(async () => {
        const element = $(selector);
        if (!element || !element.classList.contains('hidden')) { resolve(); return; }
        if (inputIsRecent()) {
          setTimeout(attempt, SURFACE_PREWARM_RETRY_MS);
          return;
        }
        const previousAria = element.getAttribute('aria-hidden');
        element.dataset.prewarming = 'true';
        element.classList.add('surface-prewarm');
        element.classList.remove('hidden');
        element.setAttribute('aria-hidden', 'true');
        element.inert = true;
        try {
          if (typeof setup === 'function') setup();
          void element.offsetHeight;
          await waitForPaint();
        } finally {
          if (element.dataset.prewarming === 'true') {
            element.classList.add('hidden');
            element.classList.remove('surface-prewarm');
            element.removeAttribute('data-prewarming');
            element.inert = false;
            if (previousAria === null) element.removeAttribute('aria-hidden');
            else element.setAttribute('aria-hidden', previousAria);
          }
          resolve();
        }
      }, SURFACE_PREWARM_TIMEOUT_MS);
    };
    attempt();
  });
}

async function prewarmInteractiveSurfaces() {
  // Settings contains every built-in theme specimen. Forcing the whole hidden
  // drawer through layout/paint used to start all preview loops and could still
  // be running when the listener opened it. The final performance stylesheet
  // now virtualizes those cards, so settings is intentionally opened lazily.
  // One surface per idle slot, with a gap, so no frame budget is ever the sum.
  await whenReadinessSettled();
  const gap = () => wait(PREWARM_SURFACE_GAP_MS);
  await prewarmSurface('#jamsOverlay', updateSharingUi); await gap();
  await prewarmSurface('#queueDrawer', renderQueue); await gap();
  await prewarmSurface('#migrationDrawer', renderMigrationReport); await gap();
  await prewarmSurface('#trackEditorOverlay'); await gap();
  await prewarmSurface('#supportOwnOverlay'); await gap();
  await prewarmSurface('#playlistPickerOverlay'); await gap();
  await prewarmSurface('#playlistCreatorOverlay');
}

function runStartupBackgroundTask(label, task, timeout = 1200) {
  const run = () => {
    scheduleIdleWork(async () => {
      if (inputIsRecent()) {
        diagnosticsState.lastStartupTask = `${label} deferred for input`;
        updateDiagnostics();
        setTimeout(run, INTERACTION_QUIET_MS);
        return;
      }
      const startedAt = performance.now();
      diagnosticsState.lastStartupTask = label;
      try {
        await task();
      } catch (error) {
        console.warn(`Pixelody startup task failed: ${label}`, error);
      } finally {
        diagnosticsState.lastStartupTaskMs = performance.now() - startedAt;
        updateDiagnostics();
      }
    }, timeout);
  };
  run();
}

function startBackgroundStartupWork(startupLoad) {
  const queueStartupTasks = () => {
    runStartupBackgroundTask('native WASAPI gate', async () => {
      await Promise.all([queryNativeWasapiHelper(), queryNativeMixerStatus()]);
    }, 700);
    runStartupBackgroundTask('J.A.M. status', refreshSharingStatus, 900);
    runStartupBackgroundTask('output scan', async () => {
      await refreshOutputs({ requestLabels: false });
      installOutputDeviceWatcher();
    }, 1200);
    runStartupBackgroundTask('mic input scan', () => refreshMicInputs({ requestLabels: false }), 1300);
    runStartupBackgroundTask('migration report', renderMigrationReport, 1400);
    runStartupBackgroundTask('watched folders sync', async () => {
      renderWatchedFoldersUi();
      if (window.desktop?.syncWatchedFolders && Array.isArray(state.watchedFolders) && state.watchedFolders.length > 0) {
        await window.desktop.syncWatchedFolders(state.watchedFolders);
      }
    }, 1500);
    runStartupBackgroundTask('surface prewarm', prewarmInteractiveSurfaces, 1700);
    runStartupBackgroundTask('metadata hydration', () => hydrateLibraryMetadata({ background: true, silent: true }), 2200);
    scheduleThemePrewarm(appearance.theme || 'studio');
  };
  // Runtime identity can select the persisted Canvas/Foreground presentation
  // and mount a different workspace host. It therefore belongs inside the
  // startup transaction, not in a task queued after the cover has disappeared.
  // Reconcile first, retarget the still-opaque receipt, then reveal only the
  // final theme. This removes loader -> Studio -> selected-theme clipping.
  const reconcileAndReveal = async () => {
    await startupUiReady;
    await initializeRuntimeInfo();
    const resolvedTheme = activePresentationKey();
    if (resolvedTheme !== startupLoad.theme) {
      startupLoad.theme = resolvedTheme;
      if (startupLoad.visible) {
        showThemeLoadScreen(resolvedTheme, APP_STARTUP_LOAD_MS, {
          mode: 'startup',
          meta: 'Opening Pixelody',
        });
      }
    }
    themePreloader?.markUsed(resolvedTheme);
    await finishStartupLoad(startupLoad);
  };
  reconcileAndReveal().then(() => {
    setTimeout(() => setReadinessState('settled'), 1040);
    queueStartupTasks();
  }).catch((error) => {
    console.warn('Pixelody startup load did not finish cleanly:', error);
    document.body.dataset.startupReveal = 'failed-closed';
    queueStartupTasks();
  });
}

