  renderDeviceProfileLibrary(); renderSpeakerSystems(); renderMicInputSelect(); updateLatencyUi(); updateMicCalibrationUi(); updateSystemTuningUi();
  renderTracks(); renderQueue(); drawCurve(); updateDiagnostics();
