  const panels = [];
  if (!layout.libraryCollapsed) panels.push({ key: 'libraryWidth', limit: grow ? limits.libraryMax : limits.libraryMin });
  if (!layout.inspectorCollapsed) panels.push({ key: 'inspectorWidth', limit: grow ? limits.inspectorMax : limits.inspectorMin });
