function installHandleDrag(element, layoutKey, minimumY) {
  let suppressClick = false;
  element.addEventListener('click', (event) => {
    if (!suppressClick) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    suppressClick = false;
  }, true);
  element.addEventListener('pointerdown', (event) => {
    if (event.button !== 0) return;
    const startY = event.clientY;
    const startTop = Number(layout[layoutKey]) || minimumY;
    let dragged = false;
    element.setPointerCapture(event.pointerId);
    const move = (moveEvent) => {
      const delta = moveEvent.clientY - startY;
      if (!dragged && Math.abs(delta) < 5) return;
      dragged = true;
      element.classList.add('dragging');
      layout[layoutKey] = startTop + delta;
      applyHandlePositions();
    };
    const end = (endEvent) => {
      element.classList.remove('dragging');
      element.removeEventListener('pointermove', move);
      element.removeEventListener('pointerup', end);
      element.removeEventListener('pointercancel', end);
      if (dragged) {
        suppressClick = endEvent.type === 'pointerup';
        setLocalStorageItem('pixelody.layout', JSON.stringify(layout));
        playInterfaceSound('swipe', { key: element, force: true });
      }
    };
    element.addEventListener('pointermove', move);
    element.addEventListener('pointerup', end);
    element.addEventListener('pointercancel', end);
  });
}
