const settingsTabTitles = { themes: 'Themes', style: 'Style & color', motion: 'Motion', personal: 'Personal', diagnostics: 'Diagnostics' };
const questSettingsTabTitles = { themes: 'Cart Select', style: 'Video Mode', motion: 'Action Speed', personal: 'Save File', diagnostics: 'Debug Screen' };
let activeSettingsTab = readPersistedString('pixelody.settingsTab', 'themes');
let activeThemeFilter = 'all';
function settingsTitleForTab(tab) {
  return cartridgeQuestExperienceActive()
    ? (questSettingsTabTitles[tab] || settingsTabTitles[tab] || 'Options')
    : (settingsTabTitles[tab] || 'Appearance');
}
function activateSettingsTab(tab) {
  activeSettingsTab = settingsTabTitles[tab] ? tab : 'themes';
  document.querySelectorAll('[data-settings-tab]').forEach((button) => {
    const active = button.dataset.settingsTab === activeSettingsTab;
    button.classList.toggle('active', active);
    button.setAttribute('aria-selected', String(active));
    button.tabIndex = active ? 0 : -1;
  });
  document.querySelectorAll('[data-settings-panel]').forEach((panel) => panel.classList.toggle('hidden', panel.dataset.settingsPanel !== activeSettingsTab));
  $('#settingsTitle').textContent = cartridgeQuestExperienceActive() ? 'Options' : 'Settings';
  $('#settingsSectionLabel').textContent = settingsTitleForTab(activeSettingsTab).toUpperCase();
  setLocalStorageItem('pixelody.settingsTab', activeSettingsTab);
  if (activeSettingsTab === 'personal') updateSignalJournalUi();
  if (activeSettingsTab === 'diagnostics') updateDiagnostics();
}

function moveSettingsTabFocus(event) {
  const tabs = [...document.querySelectorAll('[data-settings-tab]')];
  const current = event.target.closest?.('[data-settings-tab]');
  if (!current || !tabs.length) return;
  let index = tabs.indexOf(current);
  if (event.key === 'Home') index = 0;
  else if (event.key === 'End') index = tabs.length - 1;
  else if (event.key === 'ArrowRight' || event.key === 'ArrowDown') index = (index + 1) % tabs.length;
  else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') index = (index - 1 + tabs.length) % tabs.length;
  else return;
  event.preventDefault();
  const next = tabs[index];
  activateSettingsTab(next.dataset.settingsTab);
  next.focus();
}

function setCommunityThemeStatus(message, state = 'idle') {
  const status = $('#communityThemeStatus');
  if (!status) return;
  status.textContent = message;
  status.dataset.state = state;
}

function communityThemePreview(card, theme) {
  const preview = document.createElement('span');
  preview.className = 'theme-preview community-theme-preview';
  preview.setAttribute('aria-hidden', 'true');
  preview.style.setProperty('--community-primary', theme.tokens.accentPrimary);
  preview.style.setProperty('--community-state', theme.tokens.accentState);
  preview.style.setProperty('--community-canvas', theme.tokens.canvas);
  preview.style.setProperty('--community-elevation', theme.tokens.elevation2);
  preview.style.setProperty('--community-divider', theme.tokens.divider);
  preview.style.setProperty('--community-frame', theme.tokens.frame);
  for (let index = 0; index < 3; index += 1) preview.appendChild(document.createElement('i'));
  card.appendChild(preview);
}

function renderCommunityThemes() {
  const grid = $('#communityThemeGrid');
  if (!grid) return;
  grid.replaceChildren();
  for (const theme of communityThemes.values()) {
    const card = document.createElement('article');
    card.className = 'theme-option community-theme-card';
    card.dataset.themeOption = theme.runtimeKey;
    card.dataset.themeTags = `community ${theme.motion?.intensity === 'expressive' ? 'kinetic' : 'quiet'}`;
    communityThemePreview(card, theme);

    const copy = document.createElement('div');
    copy.className = 'community-theme-card-copy';
    const name = document.createElement('b');
    name.textContent = theme.name;
    const author = document.createElement('small');
    author.textContent = `by ${theme.author} · v${theme.version}`;
    const trust = document.createElement('em');
    trust.textContent = 'Local / Unreviewed · No code';
    copy.append(name, author, trust);

    const actions = document.createElement('div');
    actions.className = 'community-theme-card-actions';
    const apply = document.createElement('button');
    apply.type = 'button';
    apply.dataset.communityAction = 'apply';
    apply.dataset.communityRuntimeKey = theme.runtimeKey;
    apply.textContent = appearance.theme === theme.runtimeKey ? 'Active' : 'Apply';
    apply.disabled = appearance.theme === theme.runtimeKey;
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.dataset.communityAction = 'delete';
    remove.dataset.communityRuntimeKey = theme.runtimeKey;
    remove.title = `Delete ${theme.name}`;
    remove.setAttribute('aria-label', `Delete ${theme.name}`);
    remove.textContent = '×';
    actions.append(apply, remove);
    card.append(copy, actions);
    card.classList.toggle('active', appearance.theme === theme.runtimeKey);
    grid.appendChild(card);
  }
  if (!communityThemes.size) setCommunityThemeStatus('No local themes installed. Importing installs a package without applying it.');
  else if (communityThemeIssues.length) setCommunityThemeStatus(`${communityThemes.size} local theme${communityThemes.size === 1 ? '' : 's'} available. ${communityThemeIssues.length} invalid installed package${communityThemeIssues.length === 1 ? ' was' : 's were'} ignored.`, 'error');
  else setCommunityThemeStatus(`${communityThemes.size} local theme${communityThemes.size === 1 ? '' : 's'} installed.`, 'success');
  filterThemes();
}

async function refreshCommunityThemes(options = {}) {
  const result = await window.desktop.listThemePackages();
  if (!result?.ok) {
    setCommunityThemeStatus(result?.message || 'Installed local themes could not be read.', 'error');
    return result;
  }
  communityThemes.clear();
  (result.packages || []).forEach((theme) => {
    if (theme?.runtimeKey && theme?.tokens) communityThemes.set(theme.runtimeKey, theme);
  });
  communityThemeIssues = Array.isArray(result.issues) ? result.issues : [];
  renderCommunityThemes();
  if (options.restoreActive && String(appearance.theme || '').startsWith('community:')) {
    if (communityThemes.has(appearance.theme)) await selectTheme(appearance.theme);
    else {
      appearance.theme = 'studio';
      appearance.palette = appearance.studioPalette || 'gold';
      applyAppearance();
      scheduleDurableStatePersist(0, 'settings-change');
      navigationDispatcher.setMechanic(themeNavigationMechanics.studio);
      renderTracks({ preserveOrder: true });
      setCommunityThemeStatus('The previously selected local theme is missing or invalid. Pixelody returned to Studio.', 'error');
    }
  }
  return result;
}

function filterThemes() {
  const query = ($('#themeSearch')?.value || '').trim().toLowerCase();
  let visible = 0;
  document.querySelectorAll('[data-theme-option]').forEach((button) => {
    const matchesFilter = activeThemeFilter === 'all' || (button.dataset.themeTags || '').split(/\s+/).includes(activeThemeFilter);
    const matchesQuery = !query || button.textContent.toLowerCase().includes(query);
    const show = matchesFilter && matchesQuery;
    button.classList.toggle('hidden', !show);
    if (show) visible += 1;
  });
  $('#themeEmpty')?.classList.toggle('hidden', visible > 0);
}
