$('#importThemePackage').onclick = async () => {
  $('#importThemePackage').disabled = true;
  setCommunityThemeStatus('Inspecting the selected package...');
  try {
    const result = await window.desktop.importThemePackage();
    if (result?.canceled || result?.code === 'canceled') {
      setCommunityThemeStatus('Theme import canceled.');
      return;
    }
    if (!result?.ok) {
      setCommunityThemeStatus(result?.message || 'The selected theme package was rejected.', 'error');
      return;
    }
    await refreshCommunityThemes();
    setCommunityThemeStatus(result.duplicate ? `${result.package.name} is already installed and remains inactive.` : `${result.package.name} installed. Choose Apply when you are ready.`, 'success');
  } finally {
    $('#importThemePackage').disabled = false;
  }
};
$('#communityThemeGrid').onclick = async (event) => {
  const action = event.target.closest('[data-community-action]');
  if (!action) return;
  const theme = communityThemes.get(action.dataset.communityRuntimeKey || '');
  if (!theme) return;
  if (action.dataset.communityAction === 'apply') {
    await selectThemeFromSettings(theme.runtimeKey);
    renderCommunityThemes();
    setCommunityThemeStatus(`${theme.name} applied to the main and mini player.`, 'success');
    return;
  }
  if (action.dataset.communityAction === 'delete') {
    if (!confirm(`Delete ${theme.name} version ${theme.version} from this device?`)) return;
    if (appearance.theme === theme.runtimeKey) await selectThemeFromSettings('studio');
    const result = await window.desktop.deleteThemePackage({ id: theme.id, version: theme.version, hash: theme.hash });
    if (!result?.ok) {
      setCommunityThemeStatus(result?.message || 'The selected local theme could not be deleted.', 'error');
      return;
    }
    await refreshCommunityThemes();
    setCommunityThemeStatus(`${theme.name} was deleted from this device.`, 'success');
  }
};
