function settingsInitialFocus(tab) {
  const visibleFocusable = (element) => element && !element.disabled && element.getClientRects().length ? element : null;
  if (tab === 'themes') return visibleFocusable($('#themeSearch')) || document.querySelector('[data-settings-tab="themes"]');
  if (tab === 'personal') return visibleFocusable($('#chooseProfileImage')) || document.querySelector('[data-settings-tab="personal"]');
  return document.querySelector(`[data-settings-tab="${tab}"]`) || $('#closeSettings');
}
function openSettings(options = {}) {
  const requestedTab = settingsTabTitles[options.tab] ? options.tab : activeSettingsTab;
  const settingsOverlay = prepareSurfaceForOpen('#settingsOverlay');
  if (settingsOverlay?.classList.contains('hidden')) pushNavigationState();
  rememberNavigationOpener('settings', options.opener || document.activeElement);
  // Order matters. Revealing the overlay first meant the browser laid out and
  // painted every settings panel -- all of them ship un-hidden and only get
  // .hidden from activateSettingsTab -- and then threw that work away when the
  // inactive ones were hidden a moment later. Selecting the tab first means one
  // panel is ever laid out. Measured 7.1ms -> 2.0ms on a small library; the gap
  // widens with the size of the page behind the blur.
  activateSettingsTab(requestedTab);
  settingsOverlay?.classList.remove('hidden');
  // Appearance is already authoritative and every setting mutator synchronizes
  // its own controls. Reapplying it here invalidated the entire workspace,
  // rebuilt theme information/hero state, broadcast the mini player, and redrew
  // EQ just to reveal an existing cabinet. On the Studio rebuild that full-app
  // style pass dominated the perceived 10-20 second open.
  syncNavigationState();
  // Opening a finite, user-requested cabinet is never decorative background
  // work. Let its short transition render even if an earlier frame spike put
  // the rest of the theme into temporary Conserve mode.
  // Singularity's cabinet sits above an independently animated host; changing
  // the legacy body mode would invalidate every loaded theme selector across
  // the 2,000-row product root merely to reveal this overlay. Its accessible
  // modal state is already explicit, so preserve Conserve on this route.
  if (document.body.dataset.performance === 'conserve' && document.body.dataset.singularityProbeReady !== 'true') document.body.dataset.performance = 'balanced';
  setTimeout(() => settingsInitialFocus(requestedTab)?.focus(), 0);
}
