$('#addWatchedFolderButton').onclick = async () => {
  const result = await window.desktop.addWatchedFolder();
  if (!result || result.canceled) return;
  if (!result.ok) {
    showToast(result.error || 'Could not watch that folder.');
    return;
  }
  const folderPath = result.folderPath;
  if (folderPath && !state.watchedFolders.some((f) => f.toLowerCase() === folderPath.toLowerCase())) {
    state.watchedFolders.push(folderPath);
    persist();
  }
  if (Array.isArray(result.tracks) && result.tracks.length) {
    await addPaths(result.tracks, { sourceName: `Watched: ${nameOf(folderPath)}`, importKind: 'watch', silent: true });
    showToast(`Watching folder. Found ${result.tracks.length} track(s).`);
  } else {
    showToast(`Watching folder: ${folderPath}`);
  }
  renderWatchedFoldersUi();
};
$('#rescanWatchedFolders').onclick = async () => {
  const results = await window.desktop.rescanWatchedFolders();
  let totalAdded = 0;
  if (Array.isArray(results)) {
    for (const res of results) {
      if (res?.ok && Array.isArray(res.tracks) && res.tracks.length) {
        await addPaths(res.tracks, { sourceName: `Watched: ${nameOf(res.folderPath)}`, importKind: 'watch-rescan', silent: true });
        totalAdded += (res.added || 0);
      }
    }
  }
  showToast(totalAdded > 0 ? `Rescanned watched folders. Added ${totalAdded} new track(s).` : 'Watched folders rescanned. Library is up to date.');
  renderWatchedFoldersUi();
};
$('#watchedFoldersList').onclick = async (event) => {
  const removeButton = event.target.closest('[data-remove-watched-folder]');
  if (!removeButton) return;
  const folderPath = removeButton.dataset.removeWatchedFolder;
  if (!folderPath) return;
  await window.desktop.removeWatchedFolder(folderPath);
  state.watchedFolders = state.watchedFolders.filter((f) => f.toLowerCase() !== folderPath.toLowerCase());
  persist();
  renderWatchedFoldersUi();
  showToast('Removed watched folder.');
};
if (window.desktop?.onWatchedFolderChange) {
  window.desktop.onWatchedFolderChange(async (change) => {
    if (!change) return;
    const { addedPaths = [], removedPaths = [], folderPath } = change;
    if (addedPaths.length > 0) {
      await addPaths(addedPaths, {
        sourceName: `Watched: ${nameOf(folderPath || 'folder')}`,
        importKind: 'watch',
        silent: true,
      });
      showToast(`Added ${addedPaths.length} track(s) from watched folder.`);
    }
    if (removedPaths.length > 0) {
      const removedSet = new Set(removedPaths.map((p) => p.toLowerCase()));
      let missingCount = 0;
      state.tracks.forEach((track) => {
        if (removedSet.has(track.path.toLowerCase()) && !track.missing) {
          track.missing = true;
          missingCount++;
        }
      });
      if (missingCount > 0) {
        persist();
        renderTracks({ preserveOrder: true });
      }
    }
    renderWatchedFoldersUi();
  });
};
