function updatePlatformShortcutsUi() {
  const isMac = isMacPlatform();
  const modKey = isMac ? 'Cmd' : 'Ctrl';
  const replaceMod = (text) => (typeof text === 'string' ? text.replace(/\bCtrl\b/g, modKey) : text);
  ['#settingsButton', '#systemsButton', '#playerSystemsButton', '#compactLibraryButton', '#queueButton'].forEach((selector) => {
    const el = $(selector);
    if (el && el.title) el.title = replaceMod(el.title);
  });
  document.querySelectorAll('.shortcut-list dd').forEach((dd) => {
    if (dd.textContent) dd.textContent = replaceMod(dd.textContent);
  });
}

function syncMediaSessionPlaybackState() {
  if (!('mediaSession' in navigator)) return;
  try {
    navigator.mediaSession.playbackState = audio.paused ? 'paused' : 'playing';
    if ('setPositionState' in navigator.mediaSession && Number.isFinite(audio.duration) && audio.duration > 0) {
      navigator.mediaSession.setPositionState({
        duration: audio.duration,
        playbackRate: audio.playbackRate || 1.0,
        position: Math.min(audio.duration, Math.max(0, audio.currentTime)),
      });
    }
  } catch {}
}

